-- Coverage
CREATE TABLE "coverage" (
  "_ord" INTEGER NOT NULL UNIQUE CHECK ("_ord" >= 1),
  "coverageid" TEXT NOT NULL PRIMARY KEY CHECK (("coverageid" GLOB 'C[0-9][0-9][0-9][0-9][0-9]')),
  "materialid" TEXT NOT NULL REFERENCES "materials" ("materialid"),
  "gradeid" TEXT REFERENCES "grades" ("gradeid"),
  "gradeid_state" TEXT CHECK ("gradeid_state" IN ('Not applicable')),
  "domain" TEXT NOT NULL CHECK ("domain" IN ('AMS compatibility', 'Canadian price', 'Comparability', 'Composition', 'Grades', 'H2C status', 'Identity', 'Mandatory review', 'Measurement parsing', 'Mechanical', 'Moisture / environmental', 'Post-processing / application', 'Print setup', 'Printing', 'Research conflict', 'Source ambiguity', 'Source conflict', 'Sparse properties', 'Thermal')),
  "status" TEXT NOT NULL CHECK ("status" IN ('Conflict', 'Evidence recorded', 'Gap', 'Limited comparability', 'Not applicable', 'Partially resolved', 'Quarantined', 'Resolved', 'Reviewed with limitations', 'Superseded')),
  "manufacturer_count_text" TEXT NOT NULL CHECK ("manufacturer_count_text" IN ('Not applicable') OR (CASE WHEN json_valid("manufacturer_count_text") THEN json_type("manufacturer_count_text") END) IN ('integer', 'real') AND "manufacturer_count_text" NOT GLOB '*[^0-9eE.+-]*'),
  "manufacturer_count" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("manufacturer_count_text") THEN json_type("manufacturer_count_text") END) IN ('integer', 'real') AND "manufacturer_count_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("manufacturer_count_text" AS REAL) END) VIRTUAL,
  "manufacturer_count_state" TEXT GENERATED ALWAYS AS (CASE WHEN "manufacturer_count_text" IN ('Not applicable') THEN "manufacturer_count_text" END) VIRTUAL,
  "finding" TEXT NOT NULL,
  CHECK (("gradeid" IS NULL) = ("gradeid_state" IS NOT NULL)),
  CHECK (("manufacturer_count" IS NULL) = ("manufacturer_count_state" IS NOT NULL))
) STRICT;
CREATE INDEX "ix_coverage_materialid" ON "coverage" ("materialid");
CREATE INDEX "ix_coverage_gradeid" ON "coverage" ("gradeid");

