  "run_out" INTEGER GENERATED ALWAYS AS (CASE WHEN "run_out_text" IN ('TRUE', 'FALSE') THEN ("run_out_text" = 'TRUE') END) VIRTUAL,
  "run_out_state" TEXT GENERATED ALWAYS AS (CASE WHEN "run_out_text" IN ('Not applicable') THEN "run_out_text" END) VIRTUAL,
  CHECK (("stress_max_mpa" IS NULL) = ("stress_max_mpa_state" IS NOT NULL)),
  CHECK (("stress_min_mpa" IS NULL) = ("stress_min_mpa_state" IS NOT NULL)),
  CHECK (("stress_amplitude_mpa" IS NULL) = ("stress_amplitude_mpa_state" IS NOT NULL)),
  CHECK (("frequency_hz" IS NULL) = ("frequency_hz_state" IS NOT NULL)),
  CHECK (("load_ratio_r" IS NULL) = ("load_ratio_r_state" IS NOT NULL)),
  CHECK (("run_out" IS NULL) = ("run_out_state" IS NOT NULL))
) STRICT;
CREATE INDEX "ix_fatigue_tests_measurementid" ON "fatigue_tests" ("measurementid");

-- FX rates
CREATE TABLE "fx_rates" (
  "_ord" INTEGER NOT NULL UNIQUE CHECK ("_ord" >= 1),
  "currency" TEXT NOT NULL CHECK ("currency" IN ('CAD', 'EUR', 'USD')),
  "rate_date" TEXT NOT NULL CHECK ("rate_date" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "cad_per_unit_text" TEXT NOT NULL CHECK ((CASE WHEN json_valid("cad_per_unit_text") THEN json_type("cad_per_unit_text") END) IN ('integer', 'real') AND "cad_per_unit_text" NOT GLOB '*[^0-9eE.+-]*'),
  "cad_per_unit" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("cad_per_unit_text") THEN json_type("cad_per_unit_text") END) IN ('integer', 'real') AND "cad_per_unit_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("cad_per_unit_text" AS REAL) END) VIRTUAL CHECK ("cad_per_unit" >= 0),
  "sourceid" TEXT NOT NULL REFERENCES "sources" ("sourceid"),
  "locator" TEXT NOT NULL,
  "notes" TEXT NOT NULL,
  UNIQUE ("currency", "rate_date")
) STRICT;
CREATE INDEX "ix_fx_rates_sourceid" ON "fx_rates" ("sourceid");

-- Grades
CREATE TABLE "grades" (
  "_ord" INTEGER NOT NULL UNIQUE CHECK ("_ord" >= 1),
  "gradeid" TEXT NOT NULL PRIMARY KEY CHECK (("gradeid" GLOB 'G[0-9][0-9][0-9]-[0-9][0-9]' OR "gradeid" GLOB 'G[0-9][0-9][0-9]-[0-9][0-9][0-9]' OR "gradeid" GLOB 'G[0-9][0-9][0-9]-R[0-9]*')),
  "materialid" TEXT NOT NULL REFERENCES "materials" ("materialid"),
  "role" TEXT NOT NULL CHECK ("role" IN ('procurement', 'reference', 'study')),
  "status" TEXT NOT NULL CHECK ("status" IN ('active', 'retired')),
  "manufacturer" TEXT NOT NULL CHECK ("manufacturer" IN ('3D-Fuel', '3D4Makers', '3DJake', '3DXTECH', 'Anycubic', 'AzureFilm', 'Bambu Lab', 'BASF Forward AM', 'Bedrock 3D', 'BigRep', 'Braskem', 'colorFabb', 'Copper3D', 'Creality', 'CreatBot', 'Dow', 'DREMC', 'DSM', 'DuPont', 'DuPont / Celanese', 'Elegoo', 'Ensinger', 'Eryone', 'Essentium', 'eSUN', 'Eumakers', 'Extrudr', 'Fabru', 'Fiberlogy', 'Filamatrix', 'Filament2Print', 'Filamentive', 'Fillamentum', 'Flashforge', 'FormFutura', 'Grupa Azoty', 'IPCON', 'iSANMATE', 'Jamg He', 'KCL', 'Kexcelled', 'Kimya', 'Kingroon', 'LEHVOSS', 'Markforged', 'MatterHackers', 'Mitsubishi Chemical', 'Multi3D', 'Nanovia', 'nice essentials', 'NinjaTek', 'Nobufil', 'Polymaker', 'Protopasta', 'Prusa Research', 'QIDI', 'Raise3D', 'Recreus', 'Sakata 3D', 'SIDDAMENT', 'Siraya Tech', 'Smart Materials 3D', 'Spectrum', 'Stratasys', 'SUNLU', 'The Filament', 'UltiMaker', 'Xenia', 'Yousu', 'Celanese')),
  "product_name" TEXT NOT NULL,
  "shared_formulation_key" TEXT NOT NULL,
  "composition_filler" TEXT NOT NULL,
  "variant" TEXT CHECK ("variant" IN ('declared dense filler', 'lightweight additive', 'plasticised', 'undisclosed dense filler', 'flame-retardant ceramic filler', 'declared softer grade', 'luminescent pigment', 'crystallising grade', 'cosmetic dense filler')),
  "variant_state" TEXT CHECK ("variant_state" IN ('Not applicable')),
  "colour_caveat" TEXT NOT NULL,
  "availability" TEXT NOT NULL,
  "certification_claims" TEXT NOT NULL,
  "selected_grade_rationale" TEXT NOT NULL,
  "sourceid" TEXT NOT NULL REFERENCES "sources" ("sourceid"),
  "source_locator" TEXT NOT NULL,
  "diameter_compatibility" TEXT NOT NULL,
  "diameter" TEXT CHECK ("diameter" IN ('1.75 mm', '2.85 mm only', '3 mm only')),
  "diameter_state" TEXT CHECK ("diameter_state" IN ('Not published')),
  CHECK (("variant" IS NULL) = ("variant_state" IS NOT NULL)),
  CHECK (("diameter" IS NULL) = ("diameter_state" IS NOT NULL))
) STRICT;
CREATE INDEX "ix_grades_materialid" ON "grades" ("materialid");
CREATE INDEX "ix_grades_sourceid" ON "grades" ("sourceid");

-- Headline definitions
CREATE TABLE "headline_definitions" (
  "_ord" INTEGER NOT NULL UNIQUE CHECK ("_ord" >= 1),
  "headlinekey" TEXT NOT NULL PRIMARY KEY CHECK (("headlinekey" GLOB '[a-z]*')),
  "kind" TEXT NOT NULL CHECK ("kind" IN ('measurement', 'price')),
  "unit" TEXT NOT NULL,
  "value_properties" TEXT,
  "value_properties_state" TEXT CHECK ("value_properties_state" IN ('Not applicable')),
  "related_properties" TEXT,
  "related_properties_state" TEXT CHECK ("related_properties_state" IN ('Not applicable')),
  "lower_bound_properties" TEXT,
  "lower_bound_properties_state" TEXT CHECK ("lower_bound_properties_state" IN ('Not applicable')),
  "lower_bound_load_mpa_text" TEXT NOT NULL CHECK ("lower_bound_load_mpa_text" IN ('Not applicable') OR (CASE WHEN json_valid("lower_bound_load_mpa_text") THEN json_type("lower_bound_load_mpa_text") END) IN ('integer', 'real') AND "lower_bound_load_mpa_text" NOT GLOB '*[^0-9eE.+-]*'),
  "lower_bound_load_mpa" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("lower_bound_load_mpa_text") THEN json_type("lower_bound_load_mpa_text") END) IN ('integer', 'real') AND "lower_bound_load_mpa_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("lower_bound_load_mpa_text" AS REAL) END) VIRTUAL,
  "lower_bound_load_mpa_state" TEXT GENERATED ALWAYS AS (CASE WHEN "lower_bound_load_mpa_text" IN ('Not applicable') THEN "lower_bound_load_mpa_text" END) VIRTUAL,
  "lower_bound_excludes" TEXT CHECK ("lower_bound_excludes" IN ('conditioned')),
  "lower_bound_excludes_state" TEXT CHECK ("lower_bound_excludes_state" IN ('Not applicable')),
  "lower_bound_specimens" TEXT CHECK ("lower_bound_specimens" IN ('printed', 'printed or not stated')),
  "lower_bound_specimens_state" TEXT CHECK ("lower_bound_specimens_state" IN ('Not applicable')),
  "lower_bound_basis" TEXT,
  "lower_bound_basis_state" TEXT CHECK ("lower_bound_basis_state" IN ('Not applicable')),
  "direction" TEXT CHECK ("direction" IN ('45/45', 'Along flow', 'Horizontal (source label)', 'Not published', 'Stated, not a usable direction', 'Unstated', 'Vertical XZ (source label)', 'XY', 'XZ', 'YX', 'Z', 'ZX')),
  "direction_state" TEXT CHECK ("direction_state" IN ('Not applicable')),
  "unstated_direction" TEXT CHECK ("unstated_direction" IN ('flat if printed', 'excluded')),
  "unstated_direction_state" TEXT CHECK ("unstated_direction_state" IN ('Not applicable')),
  "load_mpa_text" TEXT NOT NULL CHECK ("load_mpa_text" IN ('Not applicable') OR (CASE WHEN json_valid("load_mpa_text") THEN json_type("load_mpa_text") END) IN ('integer', 'real') AND "load_mpa_text" NOT GLOB '*[^0-9eE.+-]*'),
  "load_mpa" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("load_mpa_text") THEN json_type("load_mpa_text") END) IN ('integer', 'real') AND "load_mpa_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("load_mpa_text" AS REAL) END) VIRTUAL,
  "load_mpa_state" TEXT GENERATED ALWAYS AS (CASE WHEN "load_mpa_text" IN ('Not applicable') THEN "load_mpa_text" END) VIRTUAL,
  "unstated_load" TEXT CHECK ("unstated_load" IN ('as-published', 'excluded')),
  "unstated_load_state" TEXT CHECK ("unstated_load_state" IN ('Not applicable')),
  "undescribed_bar_counts_for" TEXT,
  "undescribed_bar_counts_for_state" TEXT CHECK ("undescribed_bar_counts_for_state" IN ('Not applicable')),
  "notch" TEXT NOT NULL CHECK ("notch" IN ('Not applicable', 'Not published', 'Notched', 'Unnotched')),
  "test_temperature_c_text" TEXT NOT NULL CHECK ("test_temperature_c_text" IN ('Not applicable') OR (CASE WHEN json_valid("test_temperature_c_text") THEN json_type("test_temperature_c_text") END) IN ('integer', 'real') AND "test_temperature_c_text" NOT GLOB '*[^0-9eE.+-]*'),
  "test_temperature_c" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("test_temperature_c_text") THEN json_type("test_temperature_c_text") END) IN ('integer', 'real') AND "test_temperature_c_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("test_temperature_c_text" AS REAL) END) VIRTUAL,
  "test_temperature_c_state" TEXT GENERATED ALWAYS AS (CASE WHEN "test_temperature_c_text" IN ('Not applicable') THEN "test_temperature_c_text" END) VIRTUAL,
  "standard" TEXT CHECK ("standard" IN ('ASTM B923', 'ASTM D1004', 'ASTM D1238', 'ASTM D149', 'ASTM D150', 'ASTM D1505', 'ASTM D1525', 'ASTM D1708', 'ASTM D1822', 'ASTM D2240', 'ASTM D256', 'ASTM D257', 'ASTM D2863', 'ASTM D3418', 'ASTM D3638', 'ASTM D412', 'ASTM D4812', 'ASTM D570', 'ASTM D638', 'ASTM D648', 'ASTM D695', 'ASTM D738', 'ASTM D7426', 'ASTM D782', 'ASTM D785', 'ASTM D790', 'ASTM D792', 'ASTM D882', 'ASTM D955', 'ASTM E1356', 'ASTM E1530', 'ASTM E1952', 'ASTM E2092', 'ASTM E2402', 'ASTM E831', 'DSC', 'GB/T 1033', 'GB/T 1033.1', 'GB/T 1040', 'GB/T 1040.2', 'GB/T 1043', 'GB/T 1043.1', 'GB/T 1633', 'GB/T 1634', 'GB/T 1634.2', 'GB/T 17037.4', 'GB/T 1843', 'GB/T 19466.2', 'GB/T 31', 'GB/T 3682', 'GB/T 528', 'GB/T 531', 'GB/T 531.1', 'GB/T 9341', 'GB/T 9343', 'IEC 243', 'IEC 60093', 'IEC 60216', 'IEC 60243', 'IEC 60695', 'JIS K 7110', 'JIS K 7161', 'JIS K 7171', 'JIS K 7210', 'ISO 1133', 'ISO 11357', 'ISO 11358', 'ISO 11359', 'ISO 1182', 'ISO 1183', 'ISO 15075', 'ISO 178', 'ISO 179', 'ISO 1798', 'ISO 180', 'ISO 2039', 'ISO 22007', 'ISO 2577', 'ISO 2781', 'ISO 294', 'ISO 306', 'ISO 3146', 'ISO 3164', 'ISO 3167', 'ISO 34', 'ISO 36', 'ISO 37', 'ISO 4589', 'ISO 4649', 'ISO 52', 'ISO 527', 'ISO 572', 'ISO 604', 'ISO 62', 'ISO 6711', 'ISO 727', 'ISO 75', 'ISO 7619', 'ISO 787', 'ISO 815', 'ISO 8302', 'ISO 845', 'ISO 868', 'TGA', 'DIN 53452', 'DIN 53453', 'DIN 53455', 'DIN 53457', 'DIN 53479', 'DIN 53504', 'DIN 53505', 'DIN 53515', 'DIN 53516')),
  "standard_state" TEXT CHECK ("standard_state" IN ('Not applicable')),
  "test_scatter_text" TEXT NOT NULL CHECK ("test_scatter_text" IN ('Not applicable') OR (CASE WHEN json_valid("test_scatter_text") THEN json_type("test_scatter_text") END) IN ('integer', 'real') AND "test_scatter_text" NOT GLOB '*[^0-9eE.+-]*'),
  "test_scatter" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("test_scatter_text") THEN json_type("test_scatter_text") END) IN ('integer', 'real') AND "test_scatter_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("test_scatter_text" AS REAL) END) VIRTUAL CHECK ("test_scatter" >= 0),
  "test_scatter_state" TEXT GENERATED ALWAYS AS (CASE WHEN "test_scatter_text" IN ('Not applicable') THEN "test_scatter_text" END) VIRTUAL,
  "test_scatter_is" TEXT CHECK ("test_scatter_is" IN ('relative', 'absolute')),
  "test_scatter_is_state" TEXT CHECK ("test_scatter_is_state" IN ('Not applicable')),
  "changes_with_annealing_text" TEXT NOT NULL CHECK ("changes_with_annealing_text" IN ('TRUE', 'FALSE')),
  "changes_with_annealing" INTEGER GENERATED ALWAYS AS (CASE WHEN "changes_with_annealing_text" IN ('TRUE', 'FALSE') THEN ("changes_with_annealing_text" = 'TRUE') END) VIRTUAL,
  "changes_with_moisture_text" TEXT NOT NULL CHECK ("changes_with_moisture_text" IN ('TRUE', 'FALSE')),
  "changes_with_moisture" INTEGER GENERATED ALWAYS AS (CASE WHEN "changes_with_moisture_text" IN ('TRUE', 'FALSE') THEN ("changes_with_moisture_text" = 'TRUE') END) VIRTUAL,
  "evidence_group" TEXT CHECK ("evidence_group" IN ('mechanical', 'thermal')),
  "evidence_group_state" TEXT CHECK ("evidence_group_state" IN ('Not applicable')),
  "endpoint_note_text" TEXT NOT NULL CHECK ("endpoint_note_text" IN ('TRUE', 'FALSE')),
  "endpoint_note" INTEGER GENERATED ALWAYS AS (CASE WHEN "endpoint_note_text" IN ('TRUE', 'FALSE') THEN ("endpoint_note_text" = 'TRUE') END) VIRTUAL,
  "comparison_note" TEXT,
  "comparison_note_state" TEXT CHECK ("comparison_note_state" IN ('Not applicable')),
  "drawer_comparison" TEXT REFERENCES "drawer_comparisons" ("comparison"),
  "drawer_comparison_state" TEXT CHECK ("drawer_comparison_state" IN ('Not applicable')),
  "drawer_only_text" TEXT NOT NULL CHECK ("drawer_only_text" IN ('TRUE', 'FALSE')),
  "drawer_only" INTEGER GENERATED ALWAYS AS (CASE WHEN "drawer_only_text" IN ('TRUE', 'FALSE') THEN ("drawer_only_text" = 'TRUE') END) VIRTUAL,
  "sold_as_toughened" TEXT CHECK ("sold_as_toughened" IN ('named', 'set apart')),
  "sold_as_toughened_state" TEXT CHECK ("sold_as_toughened_state" IN ('Not applicable')),
  "short" TEXT NOT NULL,
  "plain" TEXT NOT NULL,
  "technical" TEXT NOT NULL,
  "hint" TEXT NOT NULL,
  "axis_label" TEXT NOT NULL,
  "export_header" TEXT NOT NULL UNIQUE,
  "better" TEXT NOT NULL CHECK ("better" IN ('min', 'max')),
  "filter_group" TEXT NOT NULL CHECK ("filter_group" IN ('Compatibility', 'Cost', 'Environment', 'Evidence', 'Manufacturing', 'Mechanical', 'Thermal')),
  "filter_operator" TEXT NOT NULL CHECK ("filter_operator" IN ('>=', '<=')),
  "filter_example" TEXT NOT NULL,
  "non_negative_text" TEXT NOT NULL CHECK ("non_negative_text" IN ('TRUE', 'FALSE')),
  "non_negative" INTEGER GENERATED ALWAYS AS (CASE WHEN "non_negative_text" IN ('TRUE', 'FALSE') THEN ("non_negative_text" = 'TRUE') END) VIRTUAL,
  "table_column_text" TEXT NOT NULL CHECK ("table_column_text" IN ('TRUE', 'FALSE')),
  "table_column" INTEGER GENERATED ALWAYS AS (CASE WHEN "table_column_text" IN ('TRUE', 'FALSE') THEN ("table_column_text" = 'TRUE') END) VIRTUAL,
  "estimated_text" TEXT NOT NULL CHECK ("estimated_text" IN ('TRUE', 'FALSE')),
  "estimated" INTEGER GENERATED ALWAYS AS (CASE WHEN "estimated_text" IN ('TRUE', 'FALSE') THEN ("estimated_text" = 'TRUE') END) VIRTUAL,
  "reference_property" TEXT CHECK ("reference_property" IN ('density', 'tensileModulus', 'yieldStrength', 'tensileStrength', 'compressiveStrength', 'elongation', 'fractureToughness', 'thermalExpansion')),
  "reference_property_state" TEXT CHECK ("reference_property_state" IN ('Not applicable')),
  "applies_to" TEXT,
  "not_applicable_reason" TEXT,
  CHECK (("value_properties" IS NULL) = ("value_properties_state" IS NOT NULL)),
  CHECK (("related_properties" IS NULL) = ("related_properties_state" IS NOT NULL)),
  CHECK (("lower_bound_properties" IS NULL) = ("lower_bound_properties_state" IS NOT NULL)),
  CHECK (("lower_bound_load_mpa" IS NULL) = ("lower_bound_load_mpa_state" IS NOT NULL)),
  CHECK (("lower_bound_excludes" IS NULL) = ("lower_bound_excludes_state" IS NOT NULL)),
  CHECK (("lower_bound_specimens" IS NULL) = ("lower_bound_specimens_state" IS NOT NULL)),
  CHECK (("lower_bound_basis" IS NULL) = ("lower_bound_basis_state" IS NOT NULL)),
  CHECK (("direction" IS NULL) = ("direction_state" IS NOT NULL)),
  CHECK (("unstated_direction" IS NULL) = ("unstated_direction_state" IS NOT NULL)),
  CHECK (("load_mpa" IS NULL) = ("load_mpa_state" IS NOT NULL)),
  CHECK (("unstated_load" IS NULL) = ("unstated_load_state" IS NOT NULL)),
  CHECK (("undescribed_bar_counts_for" IS NULL) = ("undescribed_bar_counts_for_state" IS NOT NULL)),
  CHECK (("test_temperature_c" IS NULL) = ("test_temperature_c_state" IS NOT NULL)),
  CHECK (("standard" IS NULL) = ("standard_state" IS NOT NULL)),
  CHECK (("test_scatter" IS NULL) = ("test_scatter_state" IS NOT NULL)),
  CHECK (("test_scatter_is" IS NULL) = ("test_scatter_is_state" IS NOT NULL)),
  CHECK (("evidence_group" IS NULL) = ("evidence_group_state" IS NOT NULL)),
  CHECK (("comparison_note" IS NULL) = ("comparison_note_state" IS NOT NULL)),
  CHECK (("drawer_comparison" IS NULL) = ("drawer_comparison_state" IS NOT NULL)),
  CHECK (("sold_as_toughened" IS NULL) = ("sold_as_toughened_state" IS NOT NULL)),
  CHECK (("reference_property" IS NULL) = ("reference_property_state" IS NOT NULL))
) STRICT;
CREATE INDEX "ix_headline_definitions_drawer_comparison" ON "headline_definitions" ("drawer_comparison");

-- Headlines (product value pins)
CREATE TABLE "headlines" (
  "_ord" INTEGER NOT NULL UNIQUE CHECK ("_ord" >= 1),
  "materialid" TEXT NOT NULL REFERENCES "materials" ("materialid"),
  "headlinekey" TEXT NOT NULL REFERENCES "headline_definitions" ("headlinekey"),
  "measurementid" TEXT NOT NULL REFERENCES "measurements" ("measurementid") CHECK (("measurementid" GLOB 'V[0-9][0-9][0-9][0-9][0-9][0-9]')),
  "reason" TEXT NOT NULL,
  UNIQUE ("materialid", "headlinekey", "measurementid")
) STRICT;
CREATE INDEX "ix_headlines_materialid" ON "headlines" ("materialid");
CREATE INDEX "ix_headlines_headlinekey" ON "headlines" ("headlinekey");
CREATE INDEX "ix_headlines_measurementid" ON "headlines" ("measurementid");

-- Impact test guesses
CREATE TABLE "impact_test_guesses" (
  "_ord" INTEGER NOT NULL UNIQUE CHECK ("_ord" >= 1),
  "measurementid" TEXT NOT NULL PRIMARY KEY REFERENCES "measurements" ("measurementid") CHECK (("measurementid" GLOB 'V[0-9][0-9][0-9][0-9][0-9][0-9]')),
  "likely_test" TEXT NOT NULL CHECK ("likely_test" IN ('Charpy', 'Izod', 'Cannot tell', 'Another test')),
  "basis" TEXT NOT NULL,
  "reviewed_by" TEXT NOT NULL
) STRICT;
CREATE INDEX "ix_impact_test_guesses_measurementid" ON "impact_test_guesses" ("measurementid");

-- Know-how reads
CREATE TABLE "know_how_reads" (
  "_ord" INTEGER NOT NULL UNIQUE CHECK ("_ord" >= 1),
  "sourceid" TEXT NOT NULL REFERENCES "sources" ("sourceid"),
  "scope" TEXT NOT NULL CHECK ("scope" IN ('document', 'maker site')),
  "read_on" TEXT NOT NULL CHECK ("read_on" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "read_by" TEXT NOT NULL,
  UNIQUE ("sourceid", "scope")
) STRICT;
CREATE INDEX "ix_know_how_reads_sourceid" ON "know_how_reads" ("sourceid");

-- Material links
CREATE TABLE "material_links" (
  "_ord" INTEGER NOT NULL UNIQUE CHECK ("_ord" >= 1),
  "materialid" TEXT NOT NULL REFERENCES "materials" ("materialid"),
  "link" TEXT NOT NULL CHECK ("link" IN ('durability', 'h2c-status', 'printing', 'safety', 'use')),
  "recordid" TEXT NOT NULL,
  UNIQUE ("materialid", "link", "recordid")
) STRICT;
CREATE INDEX "ix_material_links_materialid" ON "material_links" ("materialid");

-- Material summaries
CREATE TABLE "material_summaries" (
  "_ord" INTEGER NOT NULL UNIQUE CHECK ("_ord" >= 1),
  "materialid" TEXT NOT NULL PRIMARY KEY REFERENCES "materials" ("materialid"),
  "summary" TEXT NOT NULL,
  "written_by" TEXT NOT NULL,
  "written_on" TEXT NOT NULL CHECK ("written_on" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "review_status" TEXT NOT NULL CHECK ("review_status" IN ('draft', 'reviewed by the owner', 'revise')),
  "notes" TEXT,
  "notes_state" TEXT CHECK ("notes_state" IN ('Not applicable')),
  CHECK (("notes" IS NULL) = ("notes_state" IS NOT NULL))
) STRICT;
CREATE INDEX "ix_material_summaries_materialid" ON "material_summaries" ("materialid");

-- Materials
CREATE TABLE "materials" (
  "_ord" INTEGER NOT NULL UNIQUE CHECK ("_ord" >= 1),
  "materialid" TEXT NOT NULL PRIMARY KEY CHECK (("materialid" GLOB 'M[0-9][0-9][0-9]')),
  "original_name" TEXT NOT NULL UNIQUE,
  "family" TEXT NOT NULL CHECK ("family" IN ('ABS', 'Acetals', 'ASA', 'Copolyesters', 'Flexible Elastomers', 'Fluoropolymers', 'High-Performance Engineering', 'Industrial High-Temperature', 'Metal and Ceramic Sintering', 'Nylon / Polyamide', 'PET Engineering', 'PETG', 'PLA', 'Polycarbonate', 'Polymer Blends', 'Polyolefins', 'PVB / Specialty Polymers', 'Styrenics', 'Support / Interface', 'Support / Soluble')),
  "h2c_status" TEXT NOT NULL CHECK ("h2c_status" IN ('Conditional', 'Exceeds H2C limits', 'Official Bambu product', 'Officially listed family', 'Theoretical')),
  "best_uses" TEXT NOT NULL,
  "limitations" TEXT,
  "limitations_state" TEXT CHECK ("limitations_state" IN ('Not published')),
  "full_name" TEXT NOT NULL,
  "scope" TEXT NOT NULL CHECK ("scope" IN ('Excluded', 'Family entry', 'H2C-relevant', 'Retired')),
  "abbreviation" TEXT NOT NULL UNIQUE,
  "base_polymer" TEXT NOT NULL,
  "estimate_identity" TEXT REFERENCES "polymers" ("polymerid"),
  "estimate_identity_state" TEXT CHECK ("estimate_identity_state" IN ('Not applicable')),
  "modifier_filler" TEXT NOT NULL CHECK ("modifier_filler" IN ('Aramid fibre', 'Carbon fibre', 'Ceramic', 'Commercial variant / undisclosed', 'Electrically conductive', 'ESD formulation', 'Foaming', 'Glass fibre', 'Glass spheres', 'Graphene', 'Metal powder', 'Natural fibre', 'PTFE', 'Unfilled / unspecified')),
  "variant_class" TEXT CHECK ("variant_class" IN ('particle-filled', 'silk')),
  "variant_class_state" TEXT CHECK ("variant_class_state" IN ('Not applicable')),
  "role" TEXT NOT NULL CHECK ("role" IN ('Structural / functional / appearance', 'Support/interface')),
  "identity_notes" TEXT NOT NULL,
  CHECK (("limitations" IS NULL) = ("limitations_state" IS NOT NULL)),
  CHECK (("estimate_identity" IS NULL) = ("estimate_identity_state" IS NOT NULL)),
  CHECK (("variant_class" IS NULL) = ("variant_class_state" IS NOT NULL))
) STRICT;
CREATE INDEX "ix_materials_estimate_identity" ON "materials" ("estimate_identity");

-- Properties
CREATE TABLE "measurements" (
  "_ord" INTEGER NOT NULL UNIQUE CHECK ("_ord" >= 1),
  "measurementid" TEXT NOT NULL PRIMARY KEY CHECK (("measurementid" GLOB 'V[0-9][0-9][0-9][0-9][0-9][0-9]')),
  "materialid" TEXT NOT NULL REFERENCES "materials" ("materialid"),
  "gradeid" TEXT NOT NULL REFERENCES "grades" ("gradeid"),
  "property" TEXT NOT NULL REFERENCES "properties" ("property"),
  "raw_value" TEXT NOT NULL,
  "raw_unit" TEXT NOT NULL,
  "raw_numeric_text" TEXT NOT NULL CHECK ("raw_numeric_text" IN ('Not published', 'Not applicable') OR (CASE WHEN json_valid("raw_numeric_text") THEN json_type("raw_numeric_text") END) IN ('integer', 'real') AND "raw_numeric_text" NOT GLOB '*[^0-9eE.+-]*'),
  "raw_numeric" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("raw_numeric_text") THEN json_type("raw_numeric_text") END) IN ('integer', 'real') AND "raw_numeric_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("raw_numeric_text" AS REAL) END) VIRTUAL,
  "raw_numeric_state" TEXT GENERATED ALWAYS AS (CASE WHEN "raw_numeric_text" IN ('Not published', 'Not applicable') THEN "raw_numeric_text" END) VIRTUAL,
  "raw_uncertainty_pm_text" TEXT NOT NULL CHECK ("raw_uncertainty_pm_text" IN ('Not applicable') OR (CASE WHEN json_valid("raw_uncertainty_pm_text") THEN json_type("raw_uncertainty_pm_text") END) IN ('integer', 'real') AND "raw_uncertainty_pm_text" NOT GLOB '*[^0-9eE.+-]*'),
  "raw_uncertainty_pm" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("raw_uncertainty_pm_text") THEN json_type("raw_uncertainty_pm_text") END) IN ('integer', 'real') AND "raw_uncertainty_pm_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("raw_uncertainty_pm_text" AS REAL) END) VIRTUAL,
  "raw_uncertainty_pm_state" TEXT GENERATED ALWAYS AS (CASE WHEN "raw_uncertainty_pm_text" IN ('Not applicable') THEN "raw_uncertainty_pm_text" END) VIRTUAL,
  "raw_upper_bound_text" TEXT NOT NULL CHECK ("raw_upper_bound_text" IN ('Not applicable') OR (CASE WHEN json_valid("raw_upper_bound_text") THEN json_type("raw_upper_bound_text") END) IN ('integer', 'real') AND "raw_upper_bound_text" NOT GLOB '*[^0-9eE.+-]*'),
  "raw_upper_bound" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("raw_upper_bound_text") THEN json_type("raw_upper_bound_text") END) IN ('integer', 'real') AND "raw_upper_bound_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("raw_upper_bound_text" AS REAL) END) VIRTUAL,
  "raw_upper_bound_state" TEXT GENERATED ALWAYS AS (CASE WHEN "raw_upper_bound_text" IN ('Not applicable') THEN "raw_upper_bound_text" END) VIRTUAL,
  "operator" TEXT NOT NULL CHECK ("operator" IN ('<', '=', '>', 'Not applicable', '<=', '>=')),
  "conversion_factor_text" TEXT NOT NULL CHECK ((CASE WHEN json_valid("conversion_factor_text") THEN json_type("conversion_factor_text") END) IN ('integer', 'real') AND "conversion_factor_text" NOT GLOB '*[^0-9eE.+-]*'),
  "conversion_factor" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("conversion_factor_text") THEN json_type("conversion_factor_text") END) IN ('integer', 'real') AND "conversion_factor_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("conversion_factor_text" AS REAL) END) VIRTUAL,
  "normalized_value_text" TEXT NOT NULL CHECK ("normalized_value_text" IN ('Not published', 'Insufficient comparable data') OR (CASE WHEN json_valid("normalized_value_text") THEN json_type("normalized_value_text") END) IN ('integer', 'real') AND "normalized_value_text" NOT GLOB '*[^0-9eE.+-]*'),
  "normalized_value" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("normalized_value_text") THEN json_type("normalized_value_text") END) IN ('integer', 'real') AND "normalized_value_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("normalized_value_text" AS REAL) END) VIRTUAL,
  "normalized_value_state" TEXT GENERATED ALWAYS AS (CASE WHEN "normalized_value_text" IN ('Not published', 'Insufficient comparable data') THEN "normalized_value_text" END) VIRTUAL,
  "normalized_uncertainty_pm_text" TEXT NOT NULL CHECK ("normalized_uncertainty_pm_text" IN ('Not applicable') OR (CASE WHEN json_valid("normalized_uncertainty_pm_text") THEN json_type("normalized_uncertainty_pm_text") END) IN ('integer', 'real') AND "normalized_uncertainty_pm_text" NOT GLOB '*[^0-9eE.+-]*'),
  "normalized_uncertainty_pm" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("normalized_uncertainty_pm_text") THEN json_type("normalized_uncertainty_pm_text") END) IN ('integer', 'real') AND "normalized_uncertainty_pm_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("normalized_uncertainty_pm_text" AS REAL) END) VIRTUAL,
  "normalized_uncertainty_pm_state" TEXT GENERATED ALWAYS AS (CASE WHEN "normalized_uncertainty_pm_text" IN ('Not applicable') THEN "normalized_uncertainty_pm_text" END) VIRTUAL,
  "normalized_upper_bound_text" TEXT NOT NULL CHECK ("normalized_upper_bound_text" IN ('Not applicable') OR (CASE WHEN json_valid("normalized_upper_bound_text") THEN json_type("normalized_upper_bound_text") END) IN ('integer', 'real') AND "normalized_upper_bound_text" NOT GLOB '*[^0-9eE.+-]*'),
  "normalized_upper_bound" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("normalized_upper_bound_text") THEN json_type("normalized_upper_bound_text") END) IN ('integer', 'real') AND "normalized_upper_bound_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("normalized_upper_bound_text" AS REAL) END) VIRTUAL,
  "normalized_upper_bound_state" TEXT GENERATED ALWAYS AS (CASE WHEN "normalized_upper_bound_text" IN ('Not applicable') THEN "normalized_upper_bound_text" END) VIRTUAL,
  "normalized_unit" TEXT NOT NULL CHECK ("normalized_unit" IN ('%', '°C', 'cm³/10 min', 'cycles', 'Dimensionless', 'g/10 min', 'GPa', 'J/m', 'kg/m³', 'kJ/m²', 'kN/m', 'kV/mm', 'mm³', 'MPa', 'Not published', 'Qualitative (no fracture)', 'Rockwell M', 'Rockwell R', 'Shore (scale not specified by source)', 'Shore A', 'Shore D', 'V', 'W/(m·K)', 'µm/m/K', 'Ω', 'Ω·cm')),
  "data_status" TEXT NOT NULL CHECK ("data_status" IN ('Nominal from product designation', 'Not published', 'Published qualitative result', 'Published value', 'Published value (physically implausible)', 'Published value (transcription corrected)', 'Retired duplicate record', 'Unresolved unit / layout')),
  "specimen_type" TEXT NOT NULL CHECK ("specimen_type" IN ('Filament', 'Film specimen (ASTM D882); not a printed or moulded bar', 'Not published', 'Not published (density specimen form not explicitly established)', 'Not published (do not assume printed)', 'Not published (its document points to moulded or resin bars)', 'Printed (implied by the document)', 'Printed off the product''s recipe', 'Printed part', 'Printed part / TDS material-property section', 'Printed specimen', 'Printed specimen at partial infill', 'Printed specimen; TDS reports N/A', 'Raw material value')),
  "direction" TEXT NOT NULL CHECK ("direction" IN ('45/45', 'Along flow', 'Horizontal (source label)', 'Not applicable', 'Not published', 'Stated, not a usable direction', 'Unstated', 'Vertical XZ (source label)', 'XY', 'XZ', 'YX', 'Z', 'ZX')),
  "moisture_condition" TEXT NOT NULL,
  "moisture_state" TEXT NOT NULL CHECK ("moisture_state" IN ('dry', 'conditioned', 'not-stated')),
  "post_processing" TEXT NOT NULL,
  "post_processing_state" TEXT NOT NULL CHECK ("post_processing_state" IN ('as-printed', 'annealed', 'not-stated')),
  "anneal_c_text" TEXT NOT NULL CHECK ("anneal_c_text" IN ('Not published', 'Not applicable') OR (CASE WHEN json_valid("anneal_c_text") THEN json_type("anneal_c_text") END) IN ('integer', 'real') AND "anneal_c_text" NOT GLOB '*[^0-9eE.+-]*'),
  "anneal_c" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("anneal_c_text") THEN json_type("anneal_c_text") END) IN ('integer', 'real') AND "anneal_c_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("anneal_c_text" AS REAL) END) VIRTUAL,
  "anneal_c_state" TEXT GENERATED ALWAYS AS (CASE WHEN "anneal_c_text" IN ('Not published', 'Not applicable') THEN "anneal_c_text" END) VIRTUAL,
  "anneal_h_text" TEXT NOT NULL CHECK ("anneal_h_text" IN ('Not published', 'Not applicable') OR (CASE WHEN json_valid("anneal_h_text") THEN json_type("anneal_h_text") END) IN ('integer', 'real') AND "anneal_h_text" NOT GLOB '*[^0-9eE.+-]*'),
  "anneal_h" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("anneal_h_text") THEN json_type("anneal_h_text") END) IN ('integer', 'real') AND "anneal_h_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("anneal_h_text" AS REAL) END) VIRTUAL,
  "anneal_h_state" TEXT GENERATED ALWAYS AS (CASE WHEN "anneal_h_text" IN ('Not published', 'Not applicable') THEN "anneal_h_text" END) VIRTUAL,
  "test_temperature" TEXT NOT NULL,
  "test_temperature_c_text" TEXT NOT NULL CHECK ("test_temperature_c_text" IN ('Not published') OR (CASE WHEN json_valid("test_temperature_c_text") THEN json_type("test_temperature_c_text") END) IN ('integer', 'real') AND "test_temperature_c_text" NOT GLOB '*[^0-9eE.+-]*'),
  "test_temperature_c" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("test_temperature_c_text") THEN json_type("test_temperature_c_text") END) IN ('integer', 'real') AND "test_temperature_c_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("test_temperature_c_text" AS REAL) END) VIRTUAL,
  "test_temperature_c_state" TEXT GENERATED ALWAYS AS (CASE WHEN "test_temperature_c_text" IN ('Not published') THEN "test_temperature_c_text" END) VIRTUAL,
  "standard_load" TEXT NOT NULL,
  "standards" TEXT,
  "standards_state" TEXT CHECK ("standards_state" IN ('Not published')),
  "test_load_mpa_text" TEXT NOT NULL CHECK ("test_load_mpa_text" IN ('Not applicable', 'Not published') OR (CASE WHEN json_valid("test_load_mpa_text") THEN json_type("test_load_mpa_text") END) IN ('integer', 'real') AND "test_load_mpa_text" NOT GLOB '*[^0-9eE.+-]*'),
  "test_load_mpa" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("test_load_mpa_text") THEN json_type("test_load_mpa_text") END) IN ('integer', 'real') AND "test_load_mpa_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("test_load_mpa_text" AS REAL) END) VIRTUAL,
  "test_load_mpa_state" TEXT GENERATED ALWAYS AS (CASE WHEN "test_load_mpa_text" IN ('Not applicable', 'Not published') THEN "test_load_mpa_text" END) VIRTUAL,
  "notch" TEXT NOT NULL CHECK ("notch" IN ('Not applicable', 'Not published', 'Notched', 'Unnotched')),
  "specimen_print_parameters" TEXT NOT NULL,
  "sourceid" TEXT NOT NULL REFERENCES "sources" ("sourceid"),
  "locator" TEXT NOT NULL,
  "notes" TEXT NOT NULL,
  "parse_review" TEXT NOT NULL,
  CHECK (("raw_numeric" IS NULL) = ("raw_numeric_state" IS NOT NULL)),
  CHECK (("raw_uncertainty_pm" IS NULL) = ("raw_uncertainty_pm_state" IS NOT NULL)),
  CHECK (("raw_upper_bound" IS NULL) = ("raw_upper_bound_state" IS NOT NULL)),
  CHECK (("normalized_value" IS NULL) = ("normalized_value_state" IS NOT NULL)),
  CHECK (("normalized_uncertainty_pm" IS NULL) = ("normalized_uncertainty_pm_state" IS NOT NULL)),
  CHECK (("normalized_upper_bound" IS NULL) = ("normalized_upper_bound_state" IS NOT NULL)),
  CHECK (("anneal_c" IS NULL) = ("anneal_c_state" IS NOT NULL)),
  CHECK (("anneal_h" IS NULL) = ("anneal_h_state" IS NOT NULL)),
  CHECK (("test_temperature_c" IS NULL) = ("test_temperature_c_state" IS NOT NULL)),
  CHECK (("standards" IS NULL) = ("standards_state" IS NOT NULL)),
  CHECK (("test_load_mpa" IS NULL) = ("test_load_mpa_state" IS NOT NULL))
) STRICT;
CREATE INDEX "ix_measurements_materialid" ON "measurements" ("materialid");
CREATE INDEX "ix_measurements_gradeid" ON "measurements" ("gradeid");
CREATE INDEX "ix_measurements_property" ON "measurements" ("property");
CREATE INDEX "ix_measurements_sourceid" ON "measurements" ("sourceid");

-- Method
CREATE TABLE "method" (
  "_ord" INTEGER NOT NULL UNIQUE CHECK ("_ord" >= 1),
  "section" TEXT NOT NULL CHECK ("section" IN ('Comparison', 'Evidence', 'H2C', 'Identity', 'Legacy crosswalk', 'Normalization', 'Pricing', 'Rubric', 'Scope', 'Selection', 'Verification')),
  "topic" TEXT NOT NULL PRIMARY KEY CHECK (("topic" GLOB '?*')),
  "definition_rule" TEXT NOT NULL
) STRICT;

-- Page context
CREATE TABLE "page_context" (
  "_ord" INTEGER NOT NULL UNIQUE CHECK ("_ord" >= 1),
  "pagecontextid" TEXT NOT NULL PRIMARY KEY CHECK (("pagecontextid" GLOB 'PC[0-9][0-9][0-9][0-9][0-9]')),
  "sourceid" TEXT NOT NULL REFERENCES "sources" ("sourceid"),
  "page_text" TEXT NOT NULL CHECK ((CASE WHEN json_valid("page_text") THEN json_type("page_text") END) IN ('integer') AND "page_text" NOT GLOB '*[^0-9eE.+-]*'),
  "page" INTEGER GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("page_text") THEN json_type("page_text") END) IN ('integer') AND "page_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("page_text" AS INTEGER) END) VIRTUAL CHECK ("page" >= 1),
  "applies_to" TEXT NOT NULL CHECK ("applies_to" IN ('all', 'tensile', 'flexural', 'impact', 'thermal', 'physical')),
  "table" TEXT,
  "table_state" TEXT CHECK ("table_state" IN ('Not applicable')),
  "statement" TEXT NOT NULL,
  "specimen_type" TEXT CHECK ("specimen_type" IN ('Filament', 'Film specimen (ASTM D882); not a printed or moulded bar', 'Not published (density specimen form not explicitly established)', 'Not published (do not assume printed)', 'Not published (its document points to moulded or resin bars)', 'Printed (implied by the document)', 'Printed off the product''s recipe', 'Printed part', 'Printed part / TDS material-property section', 'Printed specimen', 'Printed specimen at partial infill', 'Printed specimen; TDS reports N/A', 'Raw material value')),
  "specimen_type_state" TEXT CHECK ("specimen_type_state" IN ('Not published')),
  "moisture_state" TEXT NOT NULL CHECK ("moisture_state" IN ('dry', 'conditioned', 'not-stated')),
  "post_processing_state" TEXT NOT NULL CHECK ("post_processing_state" IN ('as-printed', 'annealed', 'not-stated')),
  "anneal_c_text" TEXT NOT NULL CHECK ("anneal_c_text" IN ('Not published', 'Not applicable') OR (CASE WHEN json_valid("anneal_c_text") THEN json_type("anneal_c_text") END) IN ('integer', 'real') AND "anneal_c_text" NOT GLOB '*[^0-9eE.+-]*'),
  "anneal_c" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("anneal_c_text") THEN json_type("anneal_c_text") END) IN ('integer', 'real') AND "anneal_c_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("anneal_c_text" AS REAL) END) VIRTUAL,
  "anneal_c_state" TEXT GENERATED ALWAYS AS (CASE WHEN "anneal_c_text" IN ('Not published', 'Not applicable') THEN "anneal_c_text" END) VIRTUAL,
  "anneal_h_text" TEXT NOT NULL CHECK ("anneal_h_text" IN ('Not published', 'Not applicable') OR (CASE WHEN json_valid("anneal_h_text") THEN json_type("anneal_h_text") END) IN ('integer', 'real') AND "anneal_h_text" NOT GLOB '*[^0-9eE.+-]*'),
  "anneal_h" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("anneal_h_text") THEN json_type("anneal_h_text") END) IN ('integer', 'real') AND "anneal_h_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("anneal_h_text" AS REAL) END) VIRTUAL,
  "anneal_h_state" TEXT GENERATED ALWAYS AS (CASE WHEN "anneal_h_text" IN ('Not published', 'Not applicable') THEN "anneal_h_text" END) VIRTUAL,
  "standard" TEXT,
  "standard_state" TEXT CHECK ("standard_state" IN ('Not published')),
  "test_temperature_c_text" TEXT NOT NULL CHECK ("test_temperature_c_text" IN ('Not published') OR (CASE WHEN json_valid("test_temperature_c_text") THEN json_type("test_temperature_c_text") END) IN ('integer', 'real') AND "test_temperature_c_text" NOT GLOB '*[^0-9eE.+-]*'),
  "test_temperature_c" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("test_temperature_c_text") THEN json_type("test_temperature_c_text") END) IN ('integer', 'real') AND "test_temperature_c_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("test_temperature_c_text" AS REAL) END) VIRTUAL,
  "test_temperature_c_state" TEXT GENERATED ALWAYS AS (CASE WHEN "test_temperature_c_text" IN ('Not published') THEN "test_temperature_c_text" END) VIRTUAL,
  "direction" TEXT CHECK ("direction" IN ('45/45', 'Along flow', 'Horizontal (source label)', 'Not applicable', 'Stated, not a usable direction', 'Unstated', 'Vertical XZ (source label)', 'XY', 'XZ', 'YX', 'Z', 'ZX')),
  "direction_state" TEXT CHECK ("direction_state" IN ('Not published')),
  "locator" TEXT NOT NULL,
  "reviewed_by" TEXT NOT NULL,
  CHECK (("table" IS NULL) = ("table_state" IS NOT NULL)),
  CHECK (("specimen_type" IS NULL) = ("specimen_type_state" IS NOT NULL)),
  CHECK (("anneal_c" IS NULL) = ("anneal_c_state" IS NOT NULL)),
  CHECK (("anneal_h" IS NULL) = ("anneal_h_state" IS NOT NULL)),
  CHECK (("standard" IS NULL) = ("standard_state" IS NOT NULL)),
  CHECK (("test_temperature_c" IS NULL) = ("test_temperature_c_state" IS NOT NULL)),
  CHECK (("direction" IS NULL) = ("direction_state" IS NOT NULL))
) STRICT;
CREATE INDEX "ix_page_context_sourceid" ON "page_context" ("sourceid");

-- Physical relations
CREATE TABLE "physical_relations" (
  "_ord" INTEGER NOT NULL UNIQUE CHECK ("_ord" >= 1),
  "relationid" TEXT NOT NULL PRIMARY KEY CHECK (("relationid" GLOB 'PR[0-9][0-9]*')),
  "lower_property" TEXT NOT NULL REFERENCES "properties" ("property"),
  "higher_property" TEXT NOT NULL REFERENCES "properties" ("property"),
  "lower_load_mpa_text" TEXT NOT NULL CHECK ("lower_load_mpa_text" IN ('Not applicable') OR (CASE WHEN json_valid("lower_load_mpa_text") THEN json_type("lower_load_mpa_text") END) IN ('integer', 'real') AND "lower_load_mpa_text" NOT GLOB '*[^0-9eE.+-]*'),
  "lower_load_mpa" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("lower_load_mpa_text") THEN json_type("lower_load_mpa_text") END) IN ('integer', 'real') AND "lower_load_mpa_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("lower_load_mpa_text" AS REAL) END) VIRTUAL,
  "lower_load_mpa_state" TEXT GENERATED ALWAYS AS (CASE WHEN "lower_load_mpa_text" IN ('Not applicable') THEN "lower_load_mpa_text" END) VIRTUAL,
  "higher_load_mpa_text" TEXT NOT NULL CHECK ("higher_load_mpa_text" IN ('Not applicable') OR (CASE WHEN json_valid("higher_load_mpa_text") THEN json_type("higher_load_mpa_text") END) IN ('integer', 'real') AND "higher_load_mpa_text" NOT GLOB '*[^0-9eE.+-]*'),
  "higher_load_mpa" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("higher_load_mpa_text") THEN json_type("higher_load_mpa_text") END) IN ('integer', 'real') AND "higher_load_mpa_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("higher_load_mpa_text" AS REAL) END) VIRTUAL,
  "higher_load_mpa_state" TEXT GENERATED ALWAYS AS (CASE WHEN "higher_load_mpa_text" IN ('Not applicable') THEN "higher_load_mpa_text" END) VIRTUAL,
  "same_test" TEXT NOT NULL,
  "relative_margin_text" TEXT NOT NULL CHECK ((CASE WHEN json_valid("relative_margin_text") THEN json_type("relative_margin_text") END) IN ('integer', 'real') AND "relative_margin_text" NOT GLOB '*[^0-9eE.+-]*'),
  "relative_margin" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("relative_margin_text") THEN json_type("relative_margin_text") END) IN ('integer', 'real') AND "relative_margin_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("relative_margin_text" AS REAL) END) VIRTUAL CHECK ("relative_margin" >= 0),
  "absolute_margin_text" TEXT NOT NULL CHECK ((CASE WHEN json_valid("absolute_margin_text") THEN json_type("absolute_margin_text") END) IN ('integer', 'real') AND "absolute_margin_text" NOT GLOB '*[^0-9eE.+-]*'),
  "absolute_margin" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("absolute_margin_text") THEN json_type("absolute_margin_text") END) IN ('integer', 'real') AND "absolute_margin_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("absolute_margin_text" AS REAL) END) VIRTUAL CHECK ("absolute_margin" >= 0),
  "applies_to" TEXT,
  "exempt_rows" TEXT CHECK ("exempt_rows" IN ('Heavy-load Vicat', 'Annealed')),
  "exempt_rows_state" TEXT CHECK ("exempt_rows_state" IN ('Not applicable')),
  "finding_code" TEXT NOT NULL CHECK ("finding_code" IN ('MEAS-PHYSICS-ORDER', 'MEAS-PHYSICS-HDT-LOADS', 'MEAS-PHYSICS-HDT-TG')),
  "finding_on" TEXT NOT NULL CHECK ("finding_on" IN ('lower', 'higher')),
  "scope" TEXT NOT NULL CHECK ("scope" IN ('measurement', 'headline', 'both')),
  "basis" TEXT NOT NULL,
  CHECK (("lower_load_mpa" IS NULL) = ("lower_load_mpa_state" IS NOT NULL)),
  CHECK (("higher_load_mpa" IS NULL) = ("higher_load_mpa_state" IS NOT NULL)),
  CHECK (("exempt_rows" IS NULL) = ("exempt_rows_state" IS NOT NULL))
) STRICT;
CREATE INDEX "ix_physical_relations_lower_property" ON "physical_relations" ("lower_property");
CREATE INDEX "ix_physical_relations_higher_property" ON "physical_relations" ("higher_property");

-- Plausibility windows
CREATE TABLE "plausibility_windows" (
  "_ord" INTEGER NOT NULL UNIQUE CHECK ("_ord" >= 1),
  "windowid" TEXT NOT NULL PRIMARY KEY CHECK (("windowid" GLOB 'W[0-9][0-9][0-9][0-9]')),
  "property" TEXT NOT NULL REFERENCES "properties" ("property"),
  "normalized_unit" TEXT NOT NULL CHECK ("normalized_unit" IN ('%', '°C', 'cm³/10 min', 'cycles', 'Dimensionless', 'g/10 min', 'GPa', 'J/m', 'kg/m³', 'kJ/m²', 'kN/m', 'kV/mm', 'mm³', 'MPa', 'Not published', 'Qualitative (no fracture)', 'Rockwell M', 'Rockwell R', 'Shore (scale not specified by source)', 'Shore A', 'Shore D', 'V', 'W/(m·K)', 'µm/m/K', 'Ω', 'Ω·cm')),
  "matrix_class" TEXT NOT NULL CHECK ("matrix_class" IN ('amorphous', 'semicrystalline', 'elastomer', 'high-temp', 'any')),
  "fill_class" TEXT NOT NULL CHECK ("fill_class" IN ('unfilled', 'fibre', 'dense', 'light', 'any')),
  "condition" TEXT NOT NULL CHECK ("condition" IN ('Notched', 'Unnotched', 'any')),
  "hard_low_text" TEXT NOT NULL CHECK ("hard_low_text" IN ('Not applicable') OR (CASE WHEN json_valid("hard_low_text") THEN json_type("hard_low_text") END) IN ('integer', 'real') AND "hard_low_text" NOT GLOB '*[^0-9eE.+-]*'),
  "hard_low" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("hard_low_text") THEN json_type("hard_low_text") END) IN ('integer', 'real') AND "hard_low_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("hard_low_text" AS REAL) END) VIRTUAL,
  "hard_low_state" TEXT GENERATED ALWAYS AS (CASE WHEN "hard_low_text" IN ('Not applicable') THEN "hard_low_text" END) VIRTUAL,
  "soft_low_text" TEXT NOT NULL CHECK ("soft_low_text" IN ('Not applicable') OR (CASE WHEN json_valid("soft_low_text") THEN json_type("soft_low_text") END) IN ('integer', 'real') AND "soft_low_text" NOT GLOB '*[^0-9eE.+-]*'),
  "soft_low" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("soft_low_text") THEN json_type("soft_low_text") END) IN ('integer', 'real') AND "soft_low_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("soft_low_text" AS REAL) END) VIRTUAL,
  "soft_low_state" TEXT GENERATED ALWAYS AS (CASE WHEN "soft_low_text" IN ('Not applicable') THEN "soft_low_text" END) VIRTUAL,
  "soft_high_text" TEXT NOT NULL CHECK ("soft_high_text" IN ('Not applicable') OR (CASE WHEN json_valid("soft_high_text") THEN json_type("soft_high_text") END) IN ('integer', 'real') AND "soft_high_text" NOT GLOB '*[^0-9eE.+-]*'),
  "soft_high" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("soft_high_text") THEN json_type("soft_high_text") END) IN ('integer', 'real') AND "soft_high_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("soft_high_text" AS REAL) END) VIRTUAL,
  "soft_high_state" TEXT GENERATED ALWAYS AS (CASE WHEN "soft_high_text" IN ('Not applicable') THEN "soft_high_text" END) VIRTUAL,
  "hard_high_text" TEXT NOT NULL CHECK ("hard_high_text" IN ('Not applicable') OR (CASE WHEN json_valid("hard_high_text") THEN json_type("hard_high_text") END) IN ('integer', 'real') AND "hard_high_text" NOT GLOB '*[^0-9eE.+-]*'),
  "hard_high" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("hard_high_text") THEN json_type("hard_high_text") END) IN ('integer', 'real') AND "hard_high_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("hard_high_text" AS REAL) END) VIRTUAL,
  "hard_high_state" TEXT GENERATED ALWAYS AS (CASE WHEN "hard_high_text" IN ('Not applicable') THEN "hard_high_text" END) VIRTUAL,
  "always_flag_text" TEXT NOT NULL CHECK ("always_flag_text" IN ('TRUE', 'FALSE')),
  "always_flag" INTEGER GENERATED ALWAYS AS (CASE WHEN "always_flag_text" IN ('TRUE', 'FALSE') THEN ("always_flag_text" = 'TRUE') END) VIRTUAL,
  "basis" TEXT NOT NULL,
  CHECK (("hard_low" IS NULL) = ("hard_low_state" IS NOT NULL)),
  CHECK (("soft_low" IS NULL) = ("soft_low_state" IS NOT NULL)),
  CHECK (("soft_high" IS NULL) = ("soft_high_state" IS NOT NULL)),
  CHECK (("hard_high" IS NULL) = ("hard_high_state" IS NOT NULL))
) STRICT;
CREATE INDEX "ix_plausibility_windows_property" ON "plausibility_windows" ("property");

-- Polymer environment
CREATE TABLE "polymer_environment" (
  "_ord" INTEGER NOT NULL UNIQUE CHECK ("_ord" >= 1),
  "polymerenvironmentid" TEXT NOT NULL PRIMARY KEY CHECK (("polymerenvironmentid" GLOB 'PB[0-9][0-9][0-9][0-9][0-9]')),
  "polymerid" TEXT NOT NULL REFERENCES "polymers" ("polymerid"),
  "category" TEXT NOT NULL CHECK ("category" IN ('acid', 'alkali', 'organic-solvent', 'oil-grease', 'water-solubility', 'uv-outdoor', 'moisture', 'hydrolysis', 'flammability', 'food-contact', 'fatigue', 'creep', 'application', 'print-quality', 'post-processing', 'specimen-prep', 'safety', 'circularity', 'limitations', 'know-how')),
  "agent" TEXT NOT NULL,
  "conditions" TEXT,
  "conditions_state" TEXT CHECK ("conditions_state" IN ('Not published')),
  "verdict" TEXT NOT NULL CHECK ("verdict" IN ('resistant', 'limited', 'not-resistant', 'soluble', 'absorbs', 'stabilised-required')),
  "finding" TEXT NOT NULL,
  "sourceid" TEXT NOT NULL REFERENCES "sources" ("sourceid"),
  "locator" TEXT NOT NULL,
  "notes" TEXT,
  "notes_state" TEXT CHECK ("notes_state" IN ('Not applicable')),
  UNIQUE ("polymerid", "category", "agent"),
  CHECK (("conditions" IS NULL) = ("conditions_state" IS NOT NULL)),
  CHECK (("notes" IS NULL) = ("notes_state" IS NOT NULL))
) STRICT;
CREATE INDEX "ix_polymer_environment_polymerid" ON "polymer_environment" ("polymerid");
CREATE INDEX "ix_polymer_environment_sourceid" ON "polymer_environment" ("sourceid");

-- Polymers
CREATE TABLE "polymers" (
  "_ord" INTEGER NOT NULL UNIQUE CHECK ("_ord" >= 1),
  "polymerid" TEXT NOT NULL PRIMARY KEY,
  "group" TEXT NOT NULL,
  "morphology" TEXT NOT NULL CHECK ("morphology" IN ('amorphous', 'semicrystalline', 'elastomer')),
  "melting_point_c_text" TEXT NOT NULL CHECK ("melting_point_c_text" IN ('Not applicable') OR (CASE WHEN json_valid("melting_point_c_text") THEN json_type("melting_point_c_text") END) IN ('integer', 'real') AND "melting_point_c_text" NOT GLOB '*[^0-9eE.+-]*'),
  "melting_point_c" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("melting_point_c_text") THEN json_type("melting_point_c_text") END) IN ('integer', 'real') AND "melting_point_c_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("melting_point_c_text" AS REAL) END) VIRTUAL,
  "melting_point_c_state" TEXT GENERATED ALWAYS AS (CASE WHEN "melting_point_c_text" IN ('Not applicable') THEN "melting_point_c_text" END) VIRTUAL,
  "as_printed" TEXT CHECK ("as_printed" IN ('crystallises while printing', 'prints amorphous', 'prints amorphous unless fibre-filled', 'crystallises, not driven by its melting point')),
  "as_printed_state" TEXT CHECK ("as_printed_state" IN ('Not applicable')),
  "can_crystallise" TEXT CHECK ("can_crystallise" IN ('yes', 'no', 'not known')),
  "can_crystallise_state" TEXT CHECK ("can_crystallise_state" IN ('Not applicable')),
  "annealing_threshold_c_text" TEXT NOT NULL CHECK ("annealing_threshold_c_text" IN ('Not applicable', 'Not recorded') OR (CASE WHEN json_valid("annealing_threshold_c_text") THEN json_type("annealing_threshold_c_text") END) IN ('integer', 'real') AND "annealing_threshold_c_text" NOT GLOB '*[^0-9eE.+-]*'),
  "annealing_threshold_c" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("annealing_threshold_c_text") THEN json_type("annealing_threshold_c_text") END) IN ('integer', 'real') AND "annealing_threshold_c_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("annealing_threshold_c_text" AS REAL) END) VIRTUAL,
  "annealing_threshold_c_state" TEXT GENERATED ALWAYS AS (CASE WHEN "annealing_threshold_c_text" IN ('Not applicable', 'Not recorded') THEN "annealing_threshold_c_text" END) VIRTUAL,
  "water_uptake" TEXT CHECK ("water_uptake" IN ('high', 'low')),
  "water_uptake_state" TEXT CHECK ("water_uptake_state" IN ('Not applicable')),
  "neat_density_min_kg_m3_text" TEXT NOT NULL CHECK ("neat_density_min_kg_m3_text" IN ('Not recorded') OR (CASE WHEN json_valid("neat_density_min_kg_m3_text") THEN json_type("neat_density_min_kg_m3_text") END) IN ('integer', 'real') AND "neat_density_min_kg_m3_text" NOT GLOB '*[^0-9eE.+-]*'),
  "neat_density_min_kg_m3" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("neat_density_min_kg_m3_text") THEN json_type("neat_density_min_kg_m3_text") END) IN ('integer', 'real') AND "neat_density_min_kg_m3_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("neat_density_min_kg_m3_text" AS REAL) END) VIRTUAL,
  "neat_density_min_kg_m3_state" TEXT GENERATED ALWAYS AS (CASE WHEN "neat_density_min_kg_m3_text" IN ('Not recorded') THEN "neat_density_min_kg_m3_text" END) VIRTUAL,
  "neat_density_max_kg_m3_text" TEXT NOT NULL CHECK ("neat_density_max_kg_m3_text" IN ('Not recorded') OR (CASE WHEN json_valid("neat_density_max_kg_m3_text") THEN json_type("neat_density_max_kg_m3_text") END) IN ('integer', 'real') AND "neat_density_max_kg_m3_text" NOT GLOB '*[^0-9eE.+-]*'),
  "neat_density_max_kg_m3" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("neat_density_max_kg_m3_text") THEN json_type("neat_density_max_kg_m3_text") END) IN ('integer', 'real') AND "neat_density_max_kg_m3_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("neat_density_max_kg_m3_text" AS REAL) END) VIRTUAL,
  "neat_density_max_kg_m3_state" TEXT GENERATED ALWAYS AS (CASE WHEN "neat_density_max_kg_m3_text" IN ('Not recorded') THEN "neat_density_max_kg_m3_text" END) VIRTUAL,
  "sourceid" TEXT REFERENCES "sources" ("sourceid"),
  "sourceid_state" TEXT CHECK ("sourceid_state" IN ('Not recorded')),
  "basis" TEXT NOT NULL,
  CHECK (("melting_point_c" IS NULL) = ("melting_point_c_state" IS NOT NULL)),
  CHECK (("as_printed" IS NULL) = ("as_printed_state" IS NOT NULL)),
  CHECK (("can_crystallise" IS NULL) = ("can_crystallise_state" IS NOT NULL)),
  CHECK (("annealing_threshold_c" IS NULL) = ("annealing_threshold_c_state" IS NOT NULL)),
  CHECK (("water_uptake" IS NULL) = ("water_uptake_state" IS NOT NULL)),
  CHECK (("neat_density_min_kg_m3" IS NULL) = ("neat_density_min_kg_m3_state" IS NOT NULL)),
  CHECK (("neat_density_max_kg_m3" IS NULL) = ("neat_density_max_kg_m3_state" IS NOT NULL)),
  CHECK (("sourceid" IS NULL) = ("sourceid_state" IS NOT NULL))
) STRICT;
CREATE INDEX "ix_polymers_sourceid" ON "polymers" ("sourceid");

-- Prices
CREATE TABLE "prices" (
  "_ord" INTEGER NOT NULL UNIQUE CHECK ("_ord" >= 1),
  "priceid" TEXT NOT NULL PRIMARY KEY CHECK (("priceid" GLOB 'CA[0-9][0-9][0-9][0-9]')),
  "materialid" TEXT NOT NULL REFERENCES "materials" ("materialid"),
  "gradeid" TEXT NOT NULL REFERENCES "grades" ("gradeid"),
  "retailer" TEXT NOT NULL,
  "variant_sku" TEXT NOT NULL,
  "packaging" TEXT NOT NULL CHECK ("packaging" IN ('Refill', 'Spool')),
  "net_mass_kg_text" TEXT NOT NULL CHECK ((CASE WHEN json_valid("net_mass_kg_text") THEN json_type("net_mass_kg_text") END) IN ('integer', 'real') AND "net_mass_kg_text" NOT GLOB '*[^0-9eE.+-]*'),
  "net_mass_kg" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("net_mass_kg_text") THEN json_type("net_mass_kg_text") END) IN ('integer', 'real') AND "net_mass_kg_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("net_mass_kg_text" AS REAL) END) VIRTUAL CHECK ("net_mass_kg" >= 0),
  "list_price_text" TEXT NOT NULL CHECK ("list_price_text" IN ('Not published') OR (CASE WHEN json_valid("list_price_text") THEN json_type("list_price_text") END) IN ('integer', 'real') AND "list_price_text" NOT GLOB '*[^0-9eE.+-]*'),
  "list_price" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("list_price_text") THEN json_type("list_price_text") END) IN ('integer', 'real') AND "list_price_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("list_price_text" AS REAL) END) VIRTUAL CHECK ("list_price" >= 0),
  "list_price_state" TEXT GENERATED ALWAYS AS (CASE WHEN "list_price_text" IN ('Not published') THEN "list_price_text" END) VIRTUAL,
  "sale_price_text" TEXT NOT NULL CHECK ("sale_price_text" IN ('Not applicable') OR (CASE WHEN json_valid("sale_price_text") THEN json_type("sale_price_text") END) IN ('integer', 'real') AND "sale_price_text" NOT GLOB '*[^0-9eE.+-]*'),
  "sale_price" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("sale_price_text") THEN json_type("sale_price_text") END) IN ('integer', 'real') AND "sale_price_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("sale_price_text" AS REAL) END) VIRTUAL CHECK ("sale_price" >= 0),
  "sale_price_state" TEXT GENERATED ALWAYS AS (CASE WHEN "sale_price_text" IN ('Not applicable') THEN "sale_price_text" END) VIRTUAL,
  "stock" TEXT NOT NULL CHECK ("stock" IN ('In stock', 'Out of stock')),
  "eligible_for_median_text" TEXT NOT NULL CHECK ("eligible_for_median_text" IN ('TRUE', 'FALSE')),
  "eligible_for_median" INTEGER GENERATED ALWAYS AS (CASE WHEN "eligible_for_median_text" IN ('TRUE', 'FALSE') THEN ("eligible_for_median_text" = 'TRUE') END) VIRTUAL,
  "headline_sample_text" TEXT NOT NULL CHECK ("headline_sample_text" IN ('TRUE', 'FALSE')),
  "headline_sample" INTEGER GENERATED ALWAYS AS (CASE WHEN "headline_sample_text" IN ('TRUE', 'FALSE') THEN ("headline_sample_text" = 'TRUE') END) VIRTUAL,
  "displayed_price_text" TEXT NOT NULL CHECK ((CASE WHEN json_valid("displayed_price_text") THEN json_type("displayed_price_text") END) IN ('integer', 'real') AND "displayed_price_text" NOT GLOB '*[^0-9eE.+-]*'),
  "displayed_price" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("displayed_price_text") THEN json_type("displayed_price_text") END) IN ('integer', 'real') AND "displayed_price_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("displayed_price_text" AS REAL) END) VIRTUAL CHECK ("displayed_price" >= 0),
  "currency" TEXT NOT NULL CHECK ("currency" IN ('CAD', 'EUR', 'USD')),
  "market" TEXT NOT NULL CHECK ("market" IN ('Amazon.ca (sold by the maker''s store)', 'Canadian storefront', 'European storefront', 'USD storefront')),
  "tax_shipping" TEXT NOT NULL,
  "vat_included_pct_text" TEXT NOT NULL CHECK ("vat_included_pct_text" IN ('Not applicable', 'Not published') OR (CASE WHEN json_valid("vat_included_pct_text") THEN json_type("vat_included_pct_text") END) IN ('integer', 'real') AND "vat_included_pct_text" NOT GLOB '*[^0-9eE.+-]*'),
  "vat_included_pct" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("vat_included_pct_text") THEN json_type("vat_included_pct_text") END) IN ('integer', 'real') AND "vat_included_pct_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("vat_included_pct_text" AS REAL) END) VIRTUAL CHECK ("vat_included_pct" >= 0) CHECK ("vat_included_pct" <= 30),
  "vat_included_pct_state" TEXT GENERATED ALWAYS AS (CASE WHEN "vat_included_pct_text" IN ('Not applicable', 'Not published') THEN "vat_included_pct_text" END) VIRTUAL,
  "regular_price_basis" TEXT NOT NULL,
  "quarantined_text" TEXT NOT NULL CHECK ("quarantined_text" IN ('TRUE', 'FALSE')),
  "quarantined" INTEGER GENERATED ALWAYS AS (CASE WHEN "quarantined_text" IN ('TRUE', 'FALSE') THEN ("quarantined_text" = 'TRUE') END) VIRTUAL,
  "url" TEXT NOT NULL CHECK (("url" GLOB 'http://*' OR "url" GLOB 'https://*')),
  "sourceid" TEXT NOT NULL REFERENCES "sources" ("sourceid"),
  "access_date" TEXT NOT NULL CHECK ("access_date" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "notes" TEXT NOT NULL,
  CHECK (("list_price" IS NULL) = ("list_price_state" IS NOT NULL)),
  CHECK (("sale_price" IS NULL) = ("sale_price_state" IS NOT NULL)),
  CHECK (("vat_included_pct" IS NULL) = ("vat_included_pct_state" IS NOT NULL))
) STRICT;
CREATE INDEX "ix_prices_materialid" ON "prices" ("materialid");
CREATE INDEX "ix_prices_gradeid" ON "prices" ("gradeid");
CREATE INDEX "ix_prices_sourceid" ON "prices" ("sourceid");

-- Print guide
CREATE TABLE "print_guide" (
