  "nozzle_min_c_state" TEXT GENERATED ALWAYS AS (CASE WHEN "nozzle_min_c_text" IN ('Not applicable', 'Not published') THEN "nozzle_min_c_text" END) VIRTUAL,
  "nozzle_max_c_text" TEXT NOT NULL CHECK ("nozzle_max_c_text" IN ('Not applicable', 'Not published') OR (CASE WHEN json_valid("nozzle_max_c_text") THEN json_type("nozzle_max_c_text") END) IN ('integer', 'real') AND "nozzle_max_c_text" NOT GLOB '*[^0-9eE.+-]*'),
  "nozzle_max_c" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("nozzle_max_c_text") THEN json_type("nozzle_max_c_text") END) IN ('integer', 'real') AND "nozzle_max_c_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("nozzle_max_c_text" AS REAL) END) VIRTUAL,
