  "nozzle_requirement" TEXT NOT NULL CHECK ("nozzle_requirement" IN ('none', 'recommended', 'required', 'unknown')),
  "bed_c" TEXT NOT NULL,
  "bed_state" TEXT NOT NULL CHECK ("bed_state" IN ('ambient', 'enclosed', 'no-setpoint', 'not-required', 'range', 'recommended', 'unknown')),
  "bed_min_c_text" TEXT NOT NULL CHECK ("bed_min_c_text" IN ('Not applicable', 'Not published') OR (CASE WHEN json_valid("bed_min_c_text") THEN json_type("bed_min_c_text") END) IN ('integer', 'real') AND "bed_min_c_text" NOT GLOB '*[^0-9eE.+-]*'),
  "bed_min_c" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("bed_min_c_text") THEN json_type("bed_min_c_text") END) IN ('integer', 'real') AND "bed_min_c_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("bed_min_c_text" AS REAL) END) VIRTUAL,
  "bed_min_c_state" TEXT GENERATED ALWAYS AS (CASE WHEN "bed_min_c_text" IN ('Not applicable', 'Not published') THEN "bed_min_c_text" END) VIRTUAL,
  "bed_max_c_text" TEXT NOT NULL CHECK ("bed_max_c_text" IN ('Not applicable', 'Not published') OR (CASE WHEN json_valid("bed_max_c_text") THEN json_type("bed_max_c_text") END) IN ('integer', 'real') AND "bed_max_c_text" NOT GLOB '*[^0-9eE.+-]*'),
  "bed_max_c" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("bed_max_c_text") THEN json_type("bed_max_c_text") END) IN ('integer', 'real') AND "bed_max_c_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("bed_max_c_text" AS REAL) END) VIRTUAL,
  "bed_max_c_state" TEXT GENERATED ALWAYS AS (CASE WHEN "bed_max_c_text" IN ('Not applicable', 'Not published') THEN "bed_max_c_text" END) VIRTUAL,
  "bed_requirement" TEXT NOT NULL CHECK ("bed_requirement" IN ('none', 'recommended', 'required', 'unknown')),
  "chamber_c" TEXT NOT NULL,
  "chamber_state" TEXT NOT NULL CHECK ("chamber_state" IN ('ambient', 'enclosed', 'no-setpoint', 'not-required', 'range', 'recommended', 'unknown')),
  "chamber_min_c_text" TEXT NOT NULL CHECK ("chamber_min_c_text" IN ('Not applicable', 'Not published') OR (CASE WHEN json_valid("chamber_min_c_text") THEN json_type("chamber_min_c_text") END) IN ('integer', 'real') AND "chamber_min_c_text" NOT GLOB '*[^0-9eE.+-]*'),
  "chamber_min_c" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("chamber_min_c_text") THEN json_type("chamber_min_c_text") END) IN ('integer', 'real') AND "chamber_min_c_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("chamber_min_c_text" AS REAL) END) VIRTUAL,
  "chamber_min_c_state" TEXT GENERATED ALWAYS AS (CASE WHEN "chamber_min_c_text" IN ('Not applicable', 'Not published') THEN "chamber_min_c_text" END) VIRTUAL,
  "chamber_max_c_text" TEXT NOT NULL CHECK ("chamber_max_c_text" IN ('Not applicable', 'Not published') OR (CASE WHEN json_valid("chamber_max_c_text") THEN json_type("chamber_max_c_text") END) IN ('integer', 'real') AND "chamber_max_c_text" NOT GLOB '*[^0-9eE.+-]*'),
  "chamber_max_c" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("chamber_max_c_text") THEN json_type("chamber_max_c_text") END) IN ('integer', 'real') AND "chamber_max_c_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("chamber_max_c_text" AS REAL) END) VIRTUAL,
  "chamber_max_c_state" TEXT GENERATED ALWAYS AS (CASE WHEN "chamber_max_c_text" IN ('Not applicable', 'Not published') THEN "chamber_max_c_text" END) VIRTUAL,
  "chamber_requirement" TEXT NOT NULL CHECK ("chamber_requirement" IN ('none', 'recommended', 'required', 'unknown')),
