  "drying_need" TEXT NOT NULL CHECK ("drying_need" IN ('required', 'optional', 'not-needed', 'unknown')),
  "drying_min_c_text" TEXT NOT NULL CHECK ("drying_min_c_text" IN ('Not applicable') OR (CASE WHEN json_valid("drying_min_c_text") THEN json_type("drying_min_c_text") END) IN ('integer', 'real') AND "drying_min_c_text" NOT GLOB '*[^0-9eE.+-]*'),
  "drying_min_c" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("drying_min_c_text") THEN json_type("drying_min_c_text") END) IN ('integer', 'real') AND "drying_min_c_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("drying_min_c_text" AS REAL) END) VIRTUAL,
  "drying_min_c_state" TEXT GENERATED ALWAYS AS (CASE WHEN "drying_min_c_text" IN ('Not applicable') THEN "drying_min_c_text" END) VIRTUAL,
  "drying_c_text" TEXT NOT NULL CHECK ("drying_c_text" IN ('Not applicable', 'Not published') OR (CASE WHEN json_valid("drying_c_text") THEN json_type("drying_c_text") END) IN ('integer', 'real') AND "drying_c_text" NOT GLOB '*[^0-9eE.+-]*'),
  "drying_c" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("drying_c_text") THEN json_type("drying_c_text") END) IN ('integer', 'real') AND "drying_c_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("drying_c_text" AS REAL) END) VIRTUAL,
  "drying_c_state" TEXT GENERATED ALWAYS AS (CASE WHEN "drying_c_text" IN ('Not applicable', 'Not published') THEN "drying_c_text" END) VIRTUAL,
  "drying_min_hours_text" TEXT NOT NULL CHECK ("drying_min_hours_text" IN ('Not applicable') OR (CASE WHEN json_valid("drying_min_hours_text") THEN json_type("drying_min_hours_text") END) IN ('integer', 'real') AND "drying_min_hours_text" NOT GLOB '*[^0-9eE.+-]*'),
