  "drying_min_hours_state" TEXT GENERATED ALWAYS AS (CASE WHEN "drying_min_hours_text" IN ('Not applicable') THEN "drying_min_hours_text" END) VIRTUAL,
  "drying_hours_text" TEXT NOT NULL CHECK ("drying_hours_text" IN ('Not applicable', 'Not published') OR (CASE WHEN json_valid("drying_hours_text") THEN json_type("drying_hours_text") END) IN ('integer', 'real') AND "drying_hours_text" NOT GLOB '*[^0-9eE.+-]*'),
  "drying_hours" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("drying_hours_text") THEN json_type("drying_hours_text") END) IN ('integer', 'real') AND "drying_hours_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("drying_hours_text" AS REAL) END) VIRTUAL,
  "drying_hours_state" TEXT GENERATED ALWAYS AS (CASE WHEN "drying_hours_text" IN ('Not applicable', 'Not published') THEN "drying_hours_text" END) VIRTUAL,
  "drying_hours_open_text" TEXT NOT NULL CHECK ("drying_hours_open_text" IN ('Not applicable') OR "drying_hours_open_text" IN ('TRUE', 'FALSE')),
  "drying_hours_open" INTEGER GENERATED ALWAYS AS (CASE WHEN "drying_hours_open_text" IN ('TRUE', 'FALSE') THEN ("drying_hours_open_text" = 'TRUE') END) VIRTUAL,
  "drying_hours_open_state" TEXT GENERATED ALWAYS AS (CASE WHEN "drying_hours_open_text" IN ('Not applicable') THEN "drying_hours_open_text" END) VIRTUAL,
  "nozzle_size_material" TEXT NOT NULL,
  "hardened_nozzle_text" TEXT NOT NULL CHECK ("hardened_nozzle_text" IN ('Not published') OR "hardened_nozzle_text" IN ('TRUE', 'FALSE')),
  "hardened_nozzle" INTEGER GENERATED ALWAYS AS (CASE WHEN "hardened_nozzle_text" IN ('TRUE', 'FALSE') THEN ("hardened_nozzle_text" = 'TRUE') END) VIRTUAL,
  "hardened_nozzle_state" TEXT GENERATED ALWAYS AS (CASE WHEN "hardened_nozzle_text" IN ('Not published') THEN "hardened_nozzle_text" END) VIRTUAL,
  "locator" TEXT NOT NULL,
  "parse_review" TEXT NOT NULL,
  UNIQUE ("sourceid", "guide_type"),
  CHECK (("nozzle_min_c" IS NULL) = ("nozzle_min_c_state" IS NOT NULL)),
  CHECK (("nozzle_max_c" IS NULL) = ("nozzle_max_c_state" IS NOT NULL)),
  CHECK (("bed_min_c" IS NULL) = ("bed_min_c_state" IS NOT NULL)),
  CHECK (("bed_max_c" IS NULL) = ("bed_max_c_state" IS NOT NULL)),
  CHECK (("chamber_min_c" IS NULL) = ("chamber_min_c_state" IS NOT NULL)),
  CHECK (("chamber_max_c" IS NULL) = ("chamber_max_c_state" IS NOT NULL)),
  CHECK (("drying_min_c" IS NULL) = ("drying_min_c_state" IS NOT NULL)),
  CHECK (("drying_c" IS NULL) = ("drying_c_state" IS NOT NULL)),
  CHECK (("drying_min_hours" IS NULL) = ("drying_min_hours_state" IS NOT NULL)),
  CHECK (("drying_hours" IS NULL) = ("drying_hours_state" IS NOT NULL)),
  CHECK (("drying_hours_open" IS NULL) = ("drying_hours_open_state" IS NOT NULL)),
  CHECK (("hardened_nozzle" IS NULL) = ("hardened_nozzle_state" IS NOT NULL))
) STRICT;
CREATE INDEX "ix_print_guide_sourceid" ON "print_guide" ("sourceid");

-- Print guide materials
CREATE TABLE "print_guide_materials" (
  "_ord" INTEGER NOT NULL UNIQUE CHECK ("_ord" >= 1),
  "materialid" TEXT NOT NULL PRIMARY KEY REFERENCES "materials" ("materialid"),
  "printguideid" TEXT NOT NULL REFERENCES "print_guide" ("printguideid"),
  "reason" TEXT NOT NULL,
  "reviewed_by" TEXT NOT NULL
) STRICT;
CREATE INDEX "ix_print_guide_materials_materialid" ON "print_guide_materials" ("materialid");
CREATE INDEX "ix_print_guide_materials_printguideid" ON "print_guide_materials" ("printguideid");

-- Product claims
CREATE TABLE "product_claims" (
  "_ord" INTEGER NOT NULL UNIQUE CHECK ("_ord" >= 1),
  "gradeid" TEXT NOT NULL REFERENCES "grades" ("gradeid"),
  "claim" TEXT NOT NULL CHECK ("claim" IN ('Toughened or impact-modified')),
  "evidenceid" TEXT NOT NULL REFERENCES "evidence" ("evidenceid") CHECK (("evidenceid" GLOB 'Q[0-9][0-9][0-9][0-9][0-9]')),
  "reason" TEXT NOT NULL,
  "reviewed_by" TEXT NOT NULL,
  UNIQUE ("gradeid", "claim")
) STRICT;
CREATE INDEX "ix_product_claims_gradeid" ON "product_claims" ("gradeid");
CREATE INDEX "ix_product_claims_evidenceid" ON "product_claims" ("evidenceid");

-- Print profile notes
CREATE TABLE "profile_notes" (
  "_ord" INTEGER NOT NULL UNIQUE CHECK ("_ord" >= 1),
  "profileid" TEXT NOT NULL REFERENCES "profiles" ("profileid"),
  "topic" TEXT NOT NULL CHECK ("topic" IN ('Adhesion / release', 'Cooling', 'Speed', 'Storage humidity', 'Warping / shrinkage', 'Bridging', 'Overhang', 'Detail / tolerance', 'Surface finish', 'Layer adhesion', 'Odour / emissions', 'Layer height', 'Shell / walls', 'Retraction', 'Drying')),
  "text" TEXT NOT NULL,
  UNIQUE ("profileid", "topic")
) STRICT;
CREATE INDEX "ix_profile_notes_profileid" ON "profile_notes" ("profileid");

-- Print setup
CREATE TABLE "profiles" (
  "_ord" INTEGER NOT NULL UNIQUE CHECK ("_ord" >= 1),
  "profileid" TEXT NOT NULL PRIMARY KEY CHECK (("profileid" GLOB 'P[0-9][0-9][0-9][0-9]')),
  "materialid" TEXT NOT NULL REFERENCES "materials" ("materialid"),
  "gradeid" TEXT NOT NULL REFERENCES "grades" ("gradeid"),
  "profile" TEXT NOT NULL CHECK ("profile" IN ('Current manufacturer product guidance', 'Manufacturer published guidance', 'Retired duplicate record')),
  "nozzle_c" TEXT NOT NULL,
  "nozzle_state" TEXT NOT NULL CHECK ("nozzle_state" IN ('ambient', 'enclosed', 'no-setpoint', 'not-required', 'range', 'recommended', 'unknown')),
  "nozzle_min_c_text" TEXT NOT NULL CHECK ("nozzle_min_c_text" IN ('Not applicable', 'Not published') OR (CASE WHEN json_valid("nozzle_min_c_text") THEN json_type("nozzle_min_c_text") END) IN ('integer', 'real') AND "nozzle_min_c_text" NOT GLOB '*[^0-9eE.+-]*'),
  "nozzle_min_c" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("nozzle_min_c_text") THEN json_type("nozzle_min_c_text") END) IN ('integer', 'real') AND "nozzle_min_c_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("nozzle_min_c_text" AS REAL) END) VIRTUAL,
  "nozzle_min_c_state" TEXT GENERATED ALWAYS AS (CASE WHEN "nozzle_min_c_text" IN ('Not applicable', 'Not published') THEN "nozzle_min_c_text" END) VIRTUAL,
  "nozzle_max_c_text" TEXT NOT NULL CHECK ("nozzle_max_c_text" IN ('Not applicable', 'Not published') OR (CASE WHEN json_valid("nozzle_max_c_text") THEN json_type("nozzle_max_c_text") END) IN ('integer', 'real') AND "nozzle_max_c_text" NOT GLOB '*[^0-9eE.+-]*'),
  "nozzle_max_c" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("nozzle_max_c_text") THEN json_type("nozzle_max_c_text") END) IN ('integer', 'real') AND "nozzle_max_c_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("nozzle_max_c_text" AS REAL) END) VIRTUAL,
  "nozzle_max_c_state" TEXT GENERATED ALWAYS AS (CASE WHEN "nozzle_max_c_text" IN ('Not applicable', 'Not published') THEN "nozzle_max_c_text" END) VIRTUAL,
  "nozzle_requirement" TEXT NOT NULL CHECK ("nozzle_requirement" IN ('none', 'recommended', 'required', 'unknown')),
  "bed_c" TEXT NOT NULL,
  "bed_state" TEXT NOT NULL CHECK ("bed_state" IN ('ambient', 'enclosed', 'no-setpoint', 'not-required', 'range', 'recommended', 'unknown')),
  "bed_min_c_text" TEXT NOT NULL CHECK ("bed_min_c_text" IN ('Not applicable', 'Not published') OR (CASE WHEN json_valid("bed_min_c_text") THEN json_type("bed_min_c_text") END) IN ('integer', 'real') AND "bed_min_c_text" NOT GLOB '*[^0-9eE.+-]*'),
  "bed_min_c" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("bed_min_c_text") THEN json_type("bed_min_c_text") END) IN ('integer', 'real') AND "bed_min_c_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("bed_min_c_text" AS REAL) END) VIRTUAL,
  "bed_min_c_state" TEXT GENERATED ALWAYS AS (CASE WHEN "bed_min_c_text" IN ('Not applicable', 'Not published') THEN "bed_min_c_text" END) VIRTUAL,
  "bed_max_c_text" TEXT NOT NULL CHECK ("bed_max_c_text" IN ('Not applicable', 'Not published') OR (CASE WHEN json_valid("bed_max_c_text") THEN json_type("bed_max_c_text") END) IN ('integer', 'real') AND "bed_max_c_text" NOT GLOB '*[^0-9eE.+-]*'),
  "bed_max_c" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("bed_max_c_text") THEN json_type("bed_max_c_text") END) IN ('integer', 'real') AND "bed_max_c_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("bed_max_c_text" AS REAL) END) VIRTUAL,
  "bed_max_c_state" TEXT GENERATED ALWAYS AS (CASE WHEN "bed_max_c_text" IN ('Not applicable', 'Not published') THEN "bed_max_c_text" END) VIRTUAL,
  "bed_requirement" TEXT NOT NULL CHECK ("bed_requirement" IN ('none', 'recommended', 'required', 'unknown')),
  "chamber_c" TEXT NOT NULL,
  "chamber_state" TEXT NOT NULL CHECK ("chamber_state" IN ('ambient', 'enclosed', 'no-setpoint', 'not-required', 'range', 'recommended', 'unknown')),
  "chamber_min_c_text" TEXT NOT NULL CHECK ("chamber_min_c_text" IN ('Not applicable', 'Not published') OR (CASE WHEN json_valid("chamber_min_c_text") THEN json_type("chamber_min_c_text") END) IN ('integer', 'real') AND "chamber_min_c_text" NOT GLOB '*[^0-9eE.+-]*'),
  "chamber_min_c" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("chamber_min_c_text") THEN json_type("chamber_min_c_text") END) IN ('integer', 'real') AND "chamber_min_c_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("chamber_min_c_text" AS REAL) END) VIRTUAL,
  "chamber_min_c_state" TEXT GENERATED ALWAYS AS (CASE WHEN "chamber_min_c_text" IN ('Not applicable', 'Not published') THEN "chamber_min_c_text" END) VIRTUAL,
  "chamber_max_c_text" TEXT NOT NULL CHECK ("chamber_max_c_text" IN ('Not applicable', 'Not published') OR (CASE WHEN json_valid("chamber_max_c_text") THEN json_type("chamber_max_c_text") END) IN ('integer', 'real') AND "chamber_max_c_text" NOT GLOB '*[^0-9eE.+-]*'),
  "chamber_max_c" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("chamber_max_c_text") THEN json_type("chamber_max_c_text") END) IN ('integer', 'real') AND "chamber_max_c_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("chamber_max_c_text" AS REAL) END) VIRTUAL,
  "chamber_max_c_state" TEXT GENERATED ALWAYS AS (CASE WHEN "chamber_max_c_text" IN ('Not applicable', 'Not published') THEN "chamber_max_c_text" END) VIRTUAL,
  "chamber_requirement" TEXT NOT NULL CHECK ("chamber_requirement" IN ('none', 'recommended', 'required', 'unknown')),
  "enclosure" TEXT NOT NULL,
  "enclosure_state" TEXT NOT NULL CHECK ("enclosure_state" IN ('not-needed', 'recommended', 'unknown')),
  "plate" TEXT NOT NULL,
  "drying" TEXT NOT NULL,
  "drying_state" TEXT NOT NULL CHECK ("drying_state" IN ('stated', 'unknown')),
  "drying_need" TEXT NOT NULL CHECK ("drying_need" IN ('required', 'optional', 'not-needed', 'unknown')),
  "drying_min_c_text" TEXT NOT NULL CHECK ("drying_min_c_text" IN ('Not applicable') OR (CASE WHEN json_valid("drying_min_c_text") THEN json_type("drying_min_c_text") END) IN ('integer', 'real') AND "drying_min_c_text" NOT GLOB '*[^0-9eE.+-]*'),
  "drying_min_c" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("drying_min_c_text") THEN json_type("drying_min_c_text") END) IN ('integer', 'real') AND "drying_min_c_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("drying_min_c_text" AS REAL) END) VIRTUAL,
  "drying_min_c_state" TEXT GENERATED ALWAYS AS (CASE WHEN "drying_min_c_text" IN ('Not applicable') THEN "drying_min_c_text" END) VIRTUAL,
  "drying_c_text" TEXT NOT NULL CHECK ("drying_c_text" IN ('Not applicable', 'Not published') OR (CASE WHEN json_valid("drying_c_text") THEN json_type("drying_c_text") END) IN ('integer', 'real') AND "drying_c_text" NOT GLOB '*[^0-9eE.+-]*'),
  "drying_c" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("drying_c_text") THEN json_type("drying_c_text") END) IN ('integer', 'real') AND "drying_c_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("drying_c_text" AS REAL) END) VIRTUAL,
  "drying_c_state" TEXT GENERATED ALWAYS AS (CASE WHEN "drying_c_text" IN ('Not applicable', 'Not published') THEN "drying_c_text" END) VIRTUAL,
  "drying_min_hours_text" TEXT NOT NULL CHECK ("drying_min_hours_text" IN ('Not applicable') OR (CASE WHEN json_valid("drying_min_hours_text") THEN json_type("drying_min_hours_text") END) IN ('integer', 'real') AND "drying_min_hours_text" NOT GLOB '*[^0-9eE.+-]*'),
  "drying_min_hours" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("drying_min_hours_text") THEN json_type("drying_min_hours_text") END) IN ('integer', 'real') AND "drying_min_hours_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("drying_min_hours_text" AS REAL) END) VIRTUAL,
  "drying_min_hours_state" TEXT GENERATED ALWAYS AS (CASE WHEN "drying_min_hours_text" IN ('Not applicable') THEN "drying_min_hours_text" END) VIRTUAL,
  "drying_hours_text" TEXT NOT NULL CHECK ("drying_hours_text" IN ('Not applicable', 'Not published') OR (CASE WHEN json_valid("drying_hours_text") THEN json_type("drying_hours_text") END) IN ('integer', 'real') AND "drying_hours_text" NOT GLOB '*[^0-9eE.+-]*'),
  "drying_hours" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("drying_hours_text") THEN json_type("drying_hours_text") END) IN ('integer', 'real') AND "drying_hours_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("drying_hours_text" AS REAL) END) VIRTUAL,
  "drying_hours_state" TEXT GENERATED ALWAYS AS (CASE WHEN "drying_hours_text" IN ('Not applicable', 'Not published') THEN "drying_hours_text" END) VIRTUAL,
  "drying_hours_open_text" TEXT NOT NULL CHECK ("drying_hours_open_text" IN ('Not applicable') OR "drying_hours_open_text" IN ('TRUE', 'FALSE')),
  "drying_hours_open" INTEGER GENERATED ALWAYS AS (CASE WHEN "drying_hours_open_text" IN ('TRUE', 'FALSE') THEN ("drying_hours_open_text" = 'TRUE') END) VIRTUAL,
  "drying_hours_open_state" TEXT GENERATED ALWAYS AS (CASE WHEN "drying_hours_open_text" IN ('Not applicable') THEN "drying_hours_open_text" END) VIRTUAL,
  "nozzle_material" TEXT NOT NULL,
  "nozzle_diameter" TEXT NOT NULL,
  "abrasion_clogging" TEXT NOT NULL,
  "hardened_nozzle_text" TEXT NOT NULL CHECK ("hardened_nozzle_text" IN ('Not published') OR "hardened_nozzle_text" IN ('TRUE', 'FALSE')),
  "hardened_nozzle" INTEGER GENERATED ALWAYS AS (CASE WHEN "hardened_nozzle_text" IN ('TRUE', 'FALSE') THEN ("hardened_nozzle_text" = 'TRUE') END) VIRTUAL,
  "hardened_nozzle_state" TEXT GENERATED ALWAYS AS (CASE WHEN "hardened_nozzle_text" IN ('Not published') THEN "hardened_nozzle_text" END) VIRTUAL,
  "h2c_left" TEXT NOT NULL,
  "h2c_right" TEXT NOT NULL,
  "ams_2_pro" TEXT NOT NULL,
  "ams_ht" TEXT NOT NULL,
  "ams_published" TEXT NOT NULL,
  "support_pairing" TEXT NOT NULL,
  "failure_modes" TEXT NOT NULL,
  "sourceid" TEXT NOT NULL REFERENCES "sources" ("sourceid"),
  "h2c_sourceid" TEXT NOT NULL,
  "locator" TEXT NOT NULL,
  "parse_review" TEXT NOT NULL,
  CHECK (("nozzle_min_c" IS NULL) = ("nozzle_min_c_state" IS NOT NULL)),
  CHECK (("nozzle_max_c" IS NULL) = ("nozzle_max_c_state" IS NOT NULL)),
  CHECK (("bed_min_c" IS NULL) = ("bed_min_c_state" IS NOT NULL)),
  CHECK (("bed_max_c" IS NULL) = ("bed_max_c_state" IS NOT NULL)),
  CHECK (("chamber_min_c" IS NULL) = ("chamber_min_c_state" IS NOT NULL)),
  CHECK (("chamber_max_c" IS NULL) = ("chamber_max_c_state" IS NOT NULL)),
  CHECK (("drying_min_c" IS NULL) = ("drying_min_c_state" IS NOT NULL)),
  CHECK (("drying_c" IS NULL) = ("drying_c_state" IS NOT NULL)),
  CHECK (("drying_min_hours" IS NULL) = ("drying_min_hours_state" IS NOT NULL)),
  CHECK (("drying_hours" IS NULL) = ("drying_hours_state" IS NOT NULL)),
  CHECK (("drying_hours_open" IS NULL) = ("drying_hours_open_state" IS NOT NULL)),
  CHECK (("hardened_nozzle" IS NULL) = ("hardened_nozzle_state" IS NOT NULL))
) STRICT;
CREATE INDEX "ix_profiles_materialid" ON "profiles" ("materialid");
CREATE INDEX "ix_profiles_gradeid" ON "profiles" ("gradeid");
CREATE INDEX "ix_profiles_sourceid" ON "profiles" ("sourceid");

-- Property registry
CREATE TABLE "properties" (
  "_ord" INTEGER NOT NULL UNIQUE CHECK ("_ord" >= 1),
  "property" TEXT NOT NULL PRIMARY KEY CHECK (("property" GLOB '[^ ]*[^ ]')),
  "domain" TEXT NOT NULL CHECK ("domain" IN ('mechanical', 'physical', 'thermal')),
  "units" TEXT NOT NULL,
  "applies_to" TEXT,
  "not_applicable_reason" TEXT,
  "description" TEXT,
  "replaced_by" TEXT REFERENCES "properties" ("property")
) STRICT;
CREATE INDEX "ix_properties_replaced_by" ON "properties" ("replaced_by");

-- Generic reference envelopes
CREATE TABLE "reference" (
  "_ord" INTEGER NOT NULL UNIQUE CHECK ("_ord" >= 1),
  "category" TEXT NOT NULL,
  "name" TEXT NOT NULL PRIMARY KEY CHECK (("name" GLOB '?*'))
) STRICT;

-- Generic reference envelopes, by property
CREATE TABLE "reference_envelopes" (
  "_ord" INTEGER NOT NULL UNIQUE CHECK ("_ord" >= 1),
  "name" TEXT NOT NULL REFERENCES "reference" ("name"),
  "property" TEXT NOT NULL CHECK ("property" IN ('density', 'tensileModulus', 'yieldStrength', 'tensileStrength', 'compressiveStrength', 'elongation', 'fractureToughness', 'thermalExpansion')),
  "min_text" TEXT NOT NULL CHECK ((CASE WHEN json_valid("min_text") THEN json_type("min_text") END) IN ('integer', 'real') AND "min_text" NOT GLOB '*[^0-9eE.+-]*'),
  "min" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("min_text") THEN json_type("min_text") END) IN ('integer', 'real') AND "min_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("min_text" AS REAL) END) VIRTUAL,
  "max_text" TEXT NOT NULL CHECK ((CASE WHEN json_valid("max_text") THEN json_type("max_text") END) IN ('integer', 'real') AND "max_text" NOT GLOB '*[^0-9eE.+-]*'),
  "max" REAL GENERATED ALWAYS AS (CASE WHEN (CASE WHEN json_valid("max_text") THEN json_type("max_text") END) IN ('integer', 'real') AND "max_text" NOT GLOB '*[^0-9eE.+-]*' THEN CAST("max_text" AS REAL) END) VIRTUAL,
  UNIQUE ("name", "property")
) STRICT;
CREATE INDEX "ix_reference_envelopes_name" ON "reference_envelopes" ("name");

-- Sources
CREATE TABLE "sources" (
  "_ord" INTEGER NOT NULL UNIQUE CHECK ("_ord" >= 1),
  "sourceid" TEXT NOT NULL PRIMARY KEY CHECK (("sourceid" GLOB '[A-Za-z0-9]*')),
  "publisher" TEXT NOT NULL,
  "title" TEXT,
  "title_state" TEXT CHECK ("title_state" IN ('Not published')),
  "revision" TEXT NOT NULL,
  "publication_date" TEXT NOT NULL CHECK (("publication_date" GLOB '[0-9][0-9][0-9][0-9]' OR "publication_date" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]' OR "publication_date" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' OR "publication_date" GLOB 'Not published')),
  "superseded_by" TEXT REFERENCES "sources" ("sourceid"),
  "superseded_by_state" TEXT CHECK ("superseded_by_state" IN ('Not applicable')),
  "access_date" TEXT NOT NULL CHECK ("access_date" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  "source_class" TEXT NOT NULL CHECK ("source_class" IN ('Manufacturer TDS', 'Manufacturer product page or guide', 'Manufacturer SDS', 'Resin supplier data sheet', 'Retailer catalogue', 'Printer documentation', 'Peer-reviewed study', 'Safety guidance', 'Reference or register')),
  "source_note" TEXT,
  "source_note_state" TEXT CHECK ("source_note_state" IN ('Not applicable')),
  "citation_role" TEXT NOT NULL CHECK ("citation_role" IN ('cited', 'corroboration', 'register', 'provenance', 'not-retrieved')),
  "url" TEXT NOT NULL,
  "locator" TEXT NOT NULL,
  "applicable_grades" TEXT NOT NULL,
  "access_state" TEXT NOT NULL CHECK ("access_state" IN ('retrieved', 'retrieved-copy', 'read-only', 'not-retrieved')),
  "access_note" TEXT,
  "access_note_state" TEXT CHECK ("access_note_state" IN ('Not applicable')),
  "sha256" TEXT NOT NULL CHECK (("sha256" GLOB '[a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9][a-f0-9]' OR "sha256" GLOB 'Not recorded' OR "sha256" GLOB 'Not applicable')),
  UNIQUE ("url", "sha256"),
  CHECK (("title" IS NULL) = ("title_state" IS NOT NULL)),
  CHECK (("superseded_by" IS NULL) = ("superseded_by_state" IS NOT NULL)),
  CHECK (("source_note" IS NULL) = ("source_note_state" IS NOT NULL)),
  CHECK (("access_note" IS NULL) = ("access_note_state" IS NOT NULL))
) STRICT;
CREATE INDEX "ix_sources_superseded_by" ON "sources" ("superseded_by");
